INSERT INTO event VALUES('evt_f4ae987060019Glqxnd0lh8jtY','ses_0b516ef36ffeY2Uc26WsdLIdZW',37,'message.part.updated.1','{"sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","part":{"id":"prt_f4ae986b30016eiStIZvxOhwJP","sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","messageID":"msg_f4ae96aca001Wfp2jbvErrInzC","type":"tool","callID":"call_5c3e685d1ea54c19b6037851","tool":"read","state":{"status":"completed","input":{"filePath":"/home/jeremy/git/operation-dbus-proto/crates/op-dbus-mirror/src/jsonrpc_interface.rs"},"output":"<path>/home/jeremy/git/operation-dbus-proto/crates/op-dbus-mirror/src/jsonrpc_interface.rs</path>\n<type>file</type>\n<content>\n1: //! JSON-RPC D-Bus Interfaces\n2: //!\n3: //! for a true 1:1 mirror of the JSON-RPC API.\n4: //!\n5: //! Authoritative Path: D-Bus method → MutationEngine.mutate → RCP Database → EventChain\n6: \n7: use op_grpc_bridge::{ChangeType, MutationEngine};\n8: use op_jsonrpc::protocol::JsonRpcRequest;\n9: use op_network::rovs_proxy::OvsdbDbusClient;\n10: use serde_json::Value;\n11: use std::sync::Arc;\n12: use zbus::interface;\n13: \n14: fn str_to_simd(s: &str) -> Result<simd_json::OwnedValue, zbus::fdo::Error> {\n15:     let mut bytes = s.as_bytes().to_vec();\n16:     simd_json::to_owned_value(&mut bytes).map_err(|e| zbus::fdo::Error::InvalidArgs(e.to_string()))\n17: }\n18: \n19: /// OVSDB D-Bus interface - mirrors JSON-RPC methods at /org/opdbus/v1/mirror/ovsdb\n20: pub struct OvsdbInterface {\n21:     pub client: Arc<OvsdbDbusClient>,\n22:     pub schema_engine: Option<Arc<MutationEngine>>,\n23: }\n24: \n25: impl OvsdbInterface {\n26:     pub fn new(client: Arc<OvsdbDbusClient>, schema_engine: Option<Arc<MutationEngine>>) -> Self {\n27:         Self {\n28:             client,\n29:             schema_engine,\n30:         }\n31:     }\n32: }\n33: \n34: #[interface(name = \"org.opdbus.mirror.OvsdbV1\")]\n35: impl OvsdbInterface {\n36:     /// Execute JSON-RPC transact on OVSDB\n37:     async fn transact(&self, operations: String) -> zbus::fdo::Result<String> {\n38:         let operations_val = str_to_simd(&operations)?;\n39: \n40:         // Route through MutationEngine for authoritative recording if available\n41:         if let Some(engine) = &self.schema_engine {\n42:             match engine\n43:                 .mutate(\n44:                     \"net\".to_string(),\n45:                     \"/org/opdbus/v1/mirror/ovsdb\".to_string(),\n46:                     ChangeType::MethodCall,\n47:                     Some(\"transact\".to_string()),\n48:                     operations_val,\n49:                     \"dbus-client\".to_string(),\n50:                     None,\n51:                 )\n52:                 .await\n53:             {\n54:                 Ok(result) => Ok(serde_json::to_string(&result.result).unwrap_or_default()),\n55:                 Err(e) => Err(zbus::fdo::Error::Failed(e.to_string())),\n56:             }\n57:         } else {\n58:             match self.client.transact_simd(operations_val).await {\n59:                 Ok(result) => Ok(serde_json::to_string(&result).unwrap_or_default()),\n60:                 Err(e) => Err(zbus::fdo::Error::Failed(e.to_string())),\n61:             }\n62:         }\n63:     }\n64: \n65:     /// Get OVSDB schema (returns list of databases as a proxy for schema info)\n66:     async fn get_schema(&self) -> zbus::fdo::Result<String> {\n67:         match self.client.list_dbs().await {\n68:             Ok(dbs) => Ok(serde_json::to_string(&dbs).unwrap_or_default()),\n69:             Err(e) => Err(zbus::fdo::Error::Failed(e.to_string())),\n70:         }\n71:     }\n72: \n73:     /// List OVSDB databases\n74:     async fn list_dbs(&self) -> zbus::fdo::Result<String> {\n75:         match self.client.list_dbs().await {\n76:             Ok(dbs) => Ok(serde_json::to_string(&dbs).unwrap_or_default()),\n77:             Err(e) => Err(zbus::fdo::Error::Failed(e.to_string())),\n78:         }\n79:     }\n80: \n81:     /// Dump entire database\n82:     async fn dump_db(&self) -> zbus::fdo::Result<String> {\n83:         match self.client.dump_db(\"Open_vSwitch\").await {\n84:             Ok(result) => Ok(serde_json::to_string(&result).unwrap_or_default()),\n85:             Err(e) => Err(zbus::fdo::Error::Failed(e.to_string())),\n86:         }\n87:     }\n88: \n89:     /// Create bridge\n90:     async fn create_bridge(&self, name: String) -> zbus::fdo::Result<()> {\n91:         if let Some(engine) = &self.schema_engine {\n92:             engine\n93:                 .mutate(\n94:                     \"net\".to_string(),\n95:                     \"/org/opdbus/v1/mirror/ovsdb\".to_string(),\n96:                     ChangeType::MethodCall,\n97:                     Some(\"create_bridge\".to_string()),\n98:                     simd_json::json!(name),\n99:                     \"dbus-client\".to_string(),\n100:                     None,\n101:                 )\n102:                 .await\n103:                 .map(|_| ())\n104:                 .map_err(|e: anyhow::Error| zbus::fdo::Error::Failed(e.to_string()))\n105:         } else {\n106:             self.client\n107:                 .create_bridge(&name)\n108:                 .await\n109:                 .map_err(|e| zbus::fdo::Error::Failed(e.to_string()))\n110:         }\n111:     }\n112: \n113:     /// Delete bridge\n114:     async fn delete_bridge(&self, name: String) -> zbus::fdo::Result<()> {\n115:         self.client\n116:             .delete_bridge(&name)\n117:             .await\n118:             .map_err(|e| zbus::fdo::Error::Failed(e.to_string()))\n119:     }\n120: \n121:     /// Add port to bridge\n122:     async fn add_port(&self, bridge: String, port: String) -> zbus::fdo::Result<()> {\n123:         if let Some(engine) = &self.schema_engine {\n124:             engine\n125:                 .mutate(\n126:                     \"net\".to_string(),\n127:                     \"/org/opdbus/v1/mirror/ovsdb\".to_string(),\n128:                     ChangeType::MethodCall,\n129: 