INSERT INTO event VALUES('evt_f4aee7d09001WNn49yW54nZL10','ses_0b516ef36ffeY2Uc26WsdLIdZW',155,'message.part.updated.1','{"sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","part":{"id":"prt_f4aee7b37001faGoPKEU2whfNM","sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","messageID":"msg_f4aee48c5001vU7JM53OauiXH9","type":"tool","callID":"call_d07e372e5ba74023bcdadbb9","tool":"read","state":{"status":"completed","input":{"filePath":"/home/jeremy/git/operation-dbus-proto/crates/op-dbus-mirror/src/event.rs"},"output":"<path>/home/jeremy/git/operation-dbus-proto/crates/op-dbus-mirror/src/event.rs</path>\n<type>file</type>\n<content>\n1: //! MirrorEvent module for unified event enum\n2: \n3: use serde_json::Value;\n4: \n5: /// Unified event enum representing all data source changes\n6: #[derive(Debug, Clone)]\n7: pub enum MirrorEvent {\n8:     /// OVSDB row change event\n9:     OvsdbRow {\n10:         table_name: String,\n11:         uuid: String,\n12:         delta: Value,\n13:         sequence: u64,\n14:     },\n15:     /// Plugin state/projection change event\n16:     Plugin {\n17:         plugin_id: String,\n18:         delta: Value,\n19:         sequence: u64,\n20:     },\n21:     /// ComponentRegistry event mirrored from the gRPC registry service\n22:     Registry {\n23:         event: Box<op_grpc_bridge::proto::registry::RegistryEvent>,\n24:         sequence: u64,\n25:     },\n26:     /// Procfs memory info event\n27:     ProcMem { delta: Value, sequence: u64 },\n28:     /// Procfs load average event\n29:     ProcLoad { delta: Value, sequence: u64 },\n30:     /// Procfs static section event\n31:     ProcStatic {\n32:         section: String,\n33:         data: Value,\n34:         sequence: u64,\n35:     },\n36: }\n37: \n38: impl MirrorEvent {\n39:     /// Get the target path for this event (mirror namespace)\n40:     pub fn target_path(&self) -> Option<String> {\n41:         match self {\n42:             MirrorEvent::OvsdbRow {\n43:                 table_name, uuid, ..\n44:             } => Some(format!(\n45:                 \"/org/opdbus/v1/mirror/ovsdb/{}/{}\",\n46:                 table_name, uuid\n47:             )),\n48:             MirrorEvent::Plugin { plugin_id, .. } => {\n49:                 Some(format!(\"/org/opdbus/v1/plugins/{}\", plugin_id))\n50:             }\n51:             MirrorEvent::Registry { event, .. } => event.component.as_ref().map(|component| {\n52:                 format!(\n53:                     \"/org/opdbus/v1/registry/components/{}\",\n54:                     component.component_id\n55:                 )\n56:             }),\n57:             MirrorEvent::ProcMem { .. } => Some(\"/org/opdbus/v1/mirror/host/meminfo\".to_string()),\n58:             MirrorEvent::ProcLoad { .. } => Some(\"/org/opdbus/v1/mirror/host/loadavg\".to_string()),\n59:             MirrorEvent::ProcStatic { section, .. } => {\n60:                 Some(format!(\"/org/opdbus/v1/mirror/host/{}\", section))\n61:             }\n62:         }\n63:     }\n64: \n65:     /// Get the sequence number for this event\n66:     pub fn sequence(&self) -> u64 {\n67:         match self {\n68:             MirrorEvent::OvsdbRow { sequence, .. }\n69:             | MirrorEvent::Plugin { sequence, .. }\n70:             | MirrorEvent::Registry { sequence, .. }\n71:             | MirrorEvent::ProcMem { sequence, .. }\n72:             | MirrorEvent::ProcLoad { sequence, .. }\n73:             | MirrorEvent::ProcStatic { sequence, .. } => *sequence,\n74:         }\n75:     }\n76: }\n\n(End of file - total 76 lines)\n</content>","title":"crates/op-dbus-mirror/src/event.rs","metadata":{"preview":"//! MirrorEvent module for unified event enum\n\nuse serde_json::Value;\n\n/// Unified event enum representing all data source changes\n#[derive(Debug, Clone)]\npub enum MirrorEvent {\n    /// OVSDB row change event\n    OvsdbRow {\n        table_name: String,\n        uuid: String,\n        delta: Value,\n        sequence: u64,\n    },\n    /// Plugin state/projection change event\n    Plugin {\n        plugin_id: String,\n        delta: Value,\n        sequence: u64,\n    },","truncated":false,"loaded":[],"display":{"type":"file","path":"/home/jeremy/git/operation-dbus-proto/crates/op-dbus-mirror/src/event.rs","text":"//! MirrorEvent module for unified event enum\n\nuse serde_json::Value;\n\n/// Unified event enum representing all data source changes\n#[derive(Debug, Clone)]\npub enum MirrorEvent {\n    /// OVSDB row change event\n    OvsdbRow {\n        table_name: String,\n        uuid: String,\n        delta: Value,\n        sequence: u64,\n    },\n    /// Plugin state/projection change event\n    Plugin {\n        plugin_id: String,\n        delta: Value,\n        sequence: u64,\n    },\n    /// ComponentRegistry event mirrored from the gRPC registry service\n    Registry {\n        event: Box<op_grpc_bridge::proto::registry::RegistryEvent>,\n        sequence: u64,\n    },\n    /// Procfs memory info event\n    ProcMem { delta: Value, sequence: u64 },\n    /// Procfs load average event\n    ProcLoad { delta: Value, sequence: u64 },\n    /// Procfs static section event\n    ProcStatic {\n        section: String,\n        data: Value,\n        sequence: u64,\n    },\n}\n\nimpl MirrorEvent {\n    /// Get the target path for this event (mirror namespace)\n    pub fn target_path(&self) -> Option<String> {\n        match self {\n            MirrorEvent::OvsdbRow {\n                table_name, uuid, ..\n            } => Some(format!(\n                \"/org/opdbus/v1/mirror/ovsdb/{}/{}\",\n                table_name, uuid\n            )),\n            MirrorEvent::Plugin { plugin_id, .. } => {\n                Some(format!(\"/org/opdbus/v1/plugins/{}\", plugin_id))\n            }\n            MirrorEvent::Registry { event, .. } => event.component.as_ref().map(|component| {\n                format!(\n                    \"/org/opdbus/v1/registry/components/{}\",\n                    component.component_id\n                )\n            }),\n            MirrorEvent::ProcMem { .. } => Some(\"/org/opdbus/v1/mirror/host/meminfo\".to_string()),\n            MirrorEvent::ProcLoad { .. } => Some(\"/org/opdbus/v1/mirror/host/loadavg\".to_string()),\n            MirrorEvent::ProcStatic { section, .. } => {\n                Some(format!(\"/org/opdbus/v1/mirror/host/{}\", section))\n            }\n        }\n    }\n\n    /// Get the sequence number for this event\n    pub fn sequence(&self) -> u64 {\n        match self {\n            MirrorEvent::OvsdbRow { sequence, .. }\n            | MirrorEvent::Plugin { sequence, .. }\n            | MirrorEvent::Registry { sequence, .. }\n            | MirrorEvent::ProcMem { sequence, .. }\n            | MirrorEvent::ProcLoad { sequence, .. }\n            | MirrorEvent::ProcStatic { sequence, .. } => *sequence,\n        }\n    }\n}","lineStart":1,"lineEnd":76,"totalLines":76,"truncated":false}},"time":{"start":1783668571168,"end":1783668571400}}},"time":1783668571400}');
