INSERT INTO event VALUES('evt_f4af755bc001y5ScKAgH3D0pU2','ses_0b516ef36ffeY2Uc26WsdLIdZW',386,'message.part.updated.1','{"sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","part":{"id":"prt_f4af755bb001THgDT4FjOIC3wL","sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","messageID":"msg_f4af7359b001BNGdiUQaU2Ze1s","type":"step-start","snapshot":"1eded3421f25f7b06d702fc82e969a2c8c54e1f9"},"time":1783669151164}');
