INSERT INTO event VALUES('evt_f4af7c99d001AnlfnJ0z5Al8Q2','ses_0b516ef36ffeY2Uc26WsdLIdZW',411,'message.part.updated.1','{"sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","part":{"id":"prt_f4af7c7d0001C8ohyy35KFKDIl","sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","messageID":"msg_f4af7b07e001X8WdOEEEKCn3hV","type":"tool","callID":"call_8362ad5efe2848f79a75e604","tool":"read","state":{"status":"completed","input":{"filePath":"/home/jeremy/git/operation-dbus-proto/crates/op-network/src/rovs_proxy.rs","limit":50,"offset":1},"output":"<path>/home/jeremy/git/operation-dbus-proto/crates/op-network/src/rovs_proxy.rs</path>\n<type>file</type>\n<content>\n1: //! D-Bus proxies for the op-openvswitch-daemon\n2: //!\n3: //! These zbus proxy types allow any crate in the workspace to call the\n4: //! hypervisor daemon through D-Bus instead of directly linking rovs_ovsdb\n5: //! or shelling out to ovs-vsctl / ovs-ofctl.\n6: //!\n7: //! Locked design (AGENTS.md §4):\n8: //! - Daemon paths: `/org/opdbus/rovs/jsonrpc` and `/org/opdbus/rovs/openflow`\n9: //! - Interfaces: `org.opdbus.rovs.jsonrpc` and `org.opdbus.rovs.openflow`\n10: //! - The daemon is a pure passthrough; business logic stays in the plugins.\n11: \n12: use anyhow::{Context, Result};\n13: use std::sync::Arc;\n14: use zbus::{proxy, Connection};\n15: \n16: // ── RovsJsonRpcProxy ──────────────────────────────────────────────────────────\n17: \n18: /// Proxy for the OVSDB JSON-RPC passthrough interface.\n19: ///\n20: /// D-Bus destination: `org.opdbus.v1.plugins.ovsdb`\n21: /// Object path: `/org/opdbus/rovs/jsonrpc`\n22: /// Interface: `org.opdbus.rovs.jsonrpc`\n23: #[proxy(\n24:     default_service = \"org.opdbus.v1.plugins.ovsdb\",\n25:     default_path = \"/org/opdbus/rovs/jsonrpc\",\n26:     interface = \"org.opdbus.rovs.jsonrpc\"\n27: )]\n28: pub trait RovsJsonRpc {\n29:     /// Execute a raw OVSDB JSON-RPC `transact`.\n30:     ///\n31:     /// `method` is the JSON-RPC method name (e.g. `\"transact\"`).\n32:     /// `params_json` is the JSON-encoded parameter array.\n33:     /// Returns the JSON-encoded result.\n34:     async fn transact(&self, method: &str, params_json: &str) -> zbus::Result<String>;\n35: \n36:     /// Execute a one-way OVSDB JSON-RPC `notify`.\n37:     async fn notify(&self, method: &str, params_json: &str) -> zbus::Result<()>;\n38: \n39:     /// Return the next JSON-RPC request id.\n40:     async fn next_id(&self) -> zbus::Result<u64>;\n41: \n42:     /// Send a raw JSON-RPC message string and return the response string.\n43:     async fn send_message(&self, msg: &str) -> zbus::Result<String>;\n44: \n45:     /// Receive a raw JSON-RPC message string.\n46:     async fn recv_message(&self) -> zbus::Result<String>;\n47: \n48:     /// Poll whether notification queue has pending items.\n49:     async fn has_pending_notifications(&self) -> zbus::Result<bool>;\n50: \n\n(Showing lines 1-50 of 820. Use offset=51 to continue.)\n</content>","title":"crates/op-network/src/rovs_proxy.rs","metadata":{"preview":"//! D-Bus proxies for the op-openvswitch-daemon\n//!\n//! These zbus proxy types allow any crate in the workspace to call the\n//! hypervisor daemon through D-Bus instead of directly linking rovs_ovsdb\n//! or shelling out to ovs-vsctl / ovs-ofctl.\n//!\n//! Locked design (AGENTS.md §4):\n//! - Daemon paths: `/org/opdbus/rovs/jsonrpc` and `/org/opdbus/rovs/openflow`\n//! - Interfaces: `org.opdbus.rovs.jsonrpc` and `org.opdbus.rovs.openflow`\n//! - The daemon is a pure passthrough; business logic stays in the plugins.\n\nuse anyhow::{Context, Result};\nuse std::sync::Arc;\nuse zbus::{proxy, Connection};\n\n// ── RovsJsonRpcProxy ──────────────────────────────────────────────────────────\n\n/// Proxy for the OVSDB JSON-RPC passthrough interface.\n///\n/// D-Bus destination: `org.opdbus.v1.plugins.ovsdb`","truncated":true,"loaded":[],"display":{"type":"file","path":"/home/jeremy/git/operation-dbus-proto/crates/op-network/src/rovs_proxy.rs","text":"//! D-Bus proxies for the op-openvswitch-daemon\n//!\n//! These zbus proxy types allow any crate in the workspace to call the\n//! hypervisor daemon through D-Bus instead of directly linking rovs_ovsdb\n//! or shelling out to ovs-vsctl / ovs-ofctl.\n//!\n//! Locked design (AGENTS.md §4):\n//! - Daemon paths: `/org/opdbus/rovs/jsonrpc` and `/org/opdbus/rovs/openflow`\n//! - Interfaces: `org.opdbus.rovs.jsonrpc` and `org.opdbus.rovs.openflow`\n//! - The daemon is a pure passthrough; business logic stays in the plugins.\n\nuse anyhow::{Context, Result};\nuse std::sync::Arc;\nuse zbus::{proxy, Connection};\n\n// ── RovsJsonRpcProxy ──────────────────────────────────────────────────────────\n\n/// Proxy for the OVSDB JSON-RPC passthrough interface.\n///\n/// D-Bus destination: `org.opdbus.v1.plugins.ovsdb`\n/// Object path: `/org/opdbus/rovs/jsonrpc`\n/// Interface: `org.opdbus.rovs.jsonrpc`\n#[proxy(\n    default_service = \"org.opdbus.v1.plugins.ovsdb\",\n    default_path = \"/org/opdbus/rovs/jsonrpc\",\n    interface = \"org.opdbus.rovs.jsonrpc\"\n)]\npub trait RovsJsonRpc {\n    /// Execute a raw OVSDB JSON-RPC `transact`.\n    ///\n    /// `method` is the JSON-RPC method name (e.g. `\"transact\"`).\n    /// `params_json` is the JSON-encoded parameter array.\n    /// Returns the JSON-encoded result.\n    async fn transact(&self, method: &str, params_json: &str) -> zbus::Result<String>;\n\n    /// Execute a one-way OVSDB JSON-RPC `notify`.\n    async fn notify(&self, method: &str, params_json: &str) -> zbus::Result<()>;\n\n    /// Return the next JSON-RPC request id.\n    async fn next_id(&self) -> zbus::Result<u64>;\n\n    /// Send a raw JSON-RPC message string and return the response string.\n    async fn send_message(&self, msg: &str) -> zbus::Result<String>;\n\n    /// Receive a raw JSON-RPC message string.\n    async fn recv_message(&self) -> zbus::Result<String>;\n\n    /// Poll whether notification queue has pending items.\n    async fn has_pending_notifications(&self) -> zbus::Result<bool>;\n","lineStart":1,"lineEnd":50,"totalLines":820,"truncated":true}},"time":{"start":1783669180813,"end":1783669180829}}},"time":1783669180829}');
