INSERT INTO event VALUES('evt_f4affd6560015O1MvmSYz8Kaql','ses_0b516ef36ffeY2Uc26WsdLIdZW',846,'message.part.updated.1','{"sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","part":{"id":"prt_f4affd540001m5LYA6PsJuiTkm","sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","messageID":"msg_f4affb1df001DAVvAhAjp3sKzy","type":"tool","callID":"call_b0666d8b4e7f4bd7bfb991f9","tool":"read","state":{"status":"completed","input":{"filePath":"/home/jeremy/git/operation-dbus-proto/crates/op-plugins/src/state_plugins/rovs_commands.rs"},"output":"<path>/home/jeremy/git/operation-dbus-proto/crates/op-plugins/src/state_plugins/rovs_commands.rs</path>\n<type>file</type>\n<content>\n1: //! rovs_commands Plugin — Direct OVSDB Command Execution via D-Bus\n2: //!\n3: //! Schema-only plugin defining callable methods for OVSDB operations.\n4: //! The grpc-bridge exposes these as D-Bus objects at `/org/opdbus/v1/plugins/rovs_commands`\n5: //! that can be called directly via zbus/busctl.\n6: //!\n7: //! Per AGENTS.md §4: D-Bus is the ONLY control plane. Methods execute OVSDB transact\n8: //! calls directly through the rovs proxy.\n9: //!\n10: //! Method input types use `schemars::JsonSchema` derive - this is the single\n11: //! source of truth for both JSON Schema (exposed in `PluginSchema.methods.args`)\n12: //! and gRPC proto generation.\n13: \n14: use op_state_store::{FieldSchema, FieldType, MethodDecl, PluginSchema, SideEffect};\n15: use schemars::JsonSchema;\n16: use serde::{Deserialize, Serialize};\n17: use simd_json::json;\n18: use simd_json::OwnedValue as Value;\n19: use std::collections::HashMap;\n20: \n21: // =============================================================================\n22: // Method input types - single source of truth via schemars\n23: // =============================================================================\n24: \n25: /// create_bridge method input\n26: #[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]\n27: pub struct CreateBridgeInput {\n28:     /// Name of the bridge to create\n29:     pub bridge_name: String,\n30:     /// Datapath type (e.g. \"system\", \"netdev\")\n31:     #[serde(default = \"default_datapath_type\")]\n32:     pub datapath_type: String,\n33: }\n34: \n35: fn default_datapath_type() -> String {\n36:     \"system\".to_string()\n37: }\n38: \n39: /// delete_bridge method input\n40: #[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]\n41: pub struct DeleteBridgeInput {\n42:     /// Name of the bridge to delete\n43:     pub bridge_name: String,\n44: }\n45: \n46: /// add_port method input\n47: #[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]\n48: pub struct AddPortInput {\n49:     /// Parent bridge name\n50:     pub bridge_name: String,\n51:     /// Port name to add\n52:     pub port_name: String,\n53:     /// Interface type (e.g. \"internal\", \"system\")\n54:     #[serde(default = \"default_interface_type\")]\n55:     pub interface_type: String,\n56: }\n57: \n58: fn default_interface_type() -> String {\n59:     \"internal\".to_string()\n60: }\n61: \n62: /// remove_port method input\n63: #[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]\n64: pub struct RemovePortInput {\n65:     /// Bridge name containing the port (optional for backward compat)\n66:     #[serde(default)]\n67:     pub bridge_name: String,\n68:     /// Port name to remove\n69:     pub port_name: String,\n70: }\n71: \n72: /// list_ports method input\n73: #[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]\n74: pub struct ListPortsInput {\n75:     /// Bridge name to query\n76:     pub bridge_name: String,\n77: }\n78: \n79: // =============================================================================\n80: // Plugin implementation\n81: // =============================================================================\n82: \n83: pub struct RovsCommandsPlugin;\n84: \n85: impl Default for RovsCommandsPlugin {\n86:     fn default() -> Self {\n87:         Self::new()\n88:     }\n89: }\n90: \n91: impl RovsCommandsPlugin {\n92:     pub fn new() -> Self {\n93:         Self\n94:     }\n95: \n96:     pub fn current_state() -> Value {\n97:         simd_json::json!({\n98:             \"available\": true,\n99:             \"schema_version\": \"1.0.0\",\n100:         })\n101:     }\n102: \n103:     pub fn schema() -> Option<PluginSchema> {\n104:         Some(rovs_commands_schema())\n105:     }\n106: }\n107: \n108: #[async_trait::async_trait]\n109: impl op_state::StatePlugin for RovsCommandsPlugin {\n110:     fn name(&self) -> &str {\n111:         \"rovs_commands\"\n112:     }\n113: \n114:     fn version(&self) -> &str {\n115:         \"1.0.0\"\n116:     }\n117: \n118:     fn schema(&self) -> Option<PluginSchema> {\n119:         Self::schema()\n120:     }\n121: \n122:     async fn calculate_diff(\n123:         &self,\n124:         _current: &Value,\n125:         _desired: &Value,\n126:     ) -> anyhow::Result<op_state::StateDiff> {\n127:         Ok(op_state::StateDiff {\n128:             plugin: self.name().to_string(),\n129:             actions: vec![],\n130:             metadata: op_state::DiffMetadata {\n131:                 timestamp: chrono::Utc::now().timestamp(),\n132:                 current_hash: \"schema-only\".to_string(),\n133:                 desired_hash: \"schema-only\".to_string(),\n134:             },\n135:         })\n136:     }\n137: \n138:     async fn apply_state(\n139:         &self,\n140:         _diff: &op_state::StateDiff,\n141:     ) -> anyhow::Result<op_state::ApplyResult> {\n142:         Ok(op_state::ApplyResult {\n143:             success: true,\n144:             changes_applied: vec![],\n145:             errors: vec![],\n146:             checkpoint: None,\n147:         })\n148:     }\n149: \n150:     async fn verify_state(&self, _desired: &Value) -> anyhow::Result<bool> {\n151:         Ok(true)\n152:     }\n153: \n154:     async fn create_checkpoint(&self) -> anyhow::Result<op_state::Checkpoint> {\n155:         Ok(op_state::Checkpoint {\n156:             id: uuid::Uuid::new_v4().to_string(),\n157:             plugin: self.name().to_string(),\n158:             timestamp: chrono::Utc::now().timestamp(),\n159:             state_snapshot: simd_json::json!(null),\n160:             backend_checkpoint: None,\n161:         })\n162:     }\n163: \n164:     async fn rollback(&self, _checkpoint: &op_state::Checkpoint) -> anyhow::Result<()> {\n165:         Ok(())\n166:     }\n167: \n168:     fn capabilities(&self) -> op_state::PluginCapabilities {\n169:         op_state::PluginCapabilities {\n170:             supports_rollback: false,\n171:             supports_checkpoints: false,\n172:             supports_verification: false,\n173:             atomic_operations: false,\n174:         }\n175:     }\n176: }\n177: \n178: pub(crate) fn rovs_commands_schema() -> PluginSchema {\n179:     let mut methods = HashMap::new();\n180:     methods.insert(\n181:         \"create_bridge\".to_string(),\n182:         super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<\n183:             CreateBridgeInput,\n184:             super::plugin_scaffold_helpers::AckOutput,\n185:         >(\n186:             \"create_bridge\",\n187:             SideEffect::Mutation,\n188:             false,\n189:             \"cap.network.ovsdb.bridge.create@v1\",\n190:             \"mut.network.ovsdb.bridge.create@v1\",\n191:         ),\n192:     );\n193:     methods.insert(\n194:         \"delete_bridge\".to_string(),\n195:         super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<\n196:             DeleteBridgeInput,\n197:             super::plugin_scaffold_helpers::AckOutput,\n198:         >(\n199:             \"delete_bridge\",\n200:             SideEffect::Mutation,\n201:             false,\n202:             \"cap.network.ovsdb.bridge.delete@v1\",\n203:             \"mut.network.ovsdb.bridge.delete@v1\",\n204:         ),\n205:     );\n206:     methods.insert(\n207:         \"add_port\".to_string(),\n208:         super::pl