INSERT INTO event VALUES('evt_f4b09f578001yjhEEV3Te3vpQl','ses_0b516ef36ffeY2Uc26WsdLIdZW',1245,'message.part.updated.1','{"sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","part":{"id":"prt_f4b09f3a0001iGkVJS06GxzgsT","sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","messageID":"msg_f4b09d770001o3sBCMLjlMi3XZ","type":"tool","callID":"call_c5ab35ecd96746489e16bc5d","tool":"read","state":{"status":"completed","input":{"filePath":"/home/jeremy/git/operation-dbus-proto/deploy/s6/gemma/run"},"output":"<path>/home/jeremy/git/operation-dbus-proto/deploy/s6/gemma/run</path>\n<type>file</type>\n<content>\n1: #!/bin/sh\n2: # Default routing loop — registry → D-Bus routing plugin → SHM → shuttle.\n3: # No LLM / xAI. Deterministic fallback when Grok is down or unused.\n4: exec 2>&1\n5: set -eu\n6: \n7: PATH=\"${PATH:-/usr/local/sbin:/usr/local/bin:/usr/bin:/bin:/home/jeremy/.local/bin}\"\n8: \n9: SHUTTLE_BIN=\"${SHUTTLE_BIN:-/usr/local/bin/op-identity-shuttle}\"\n10: GEMMA_INTERVAL_SECONDS=\"${GEMMA_INTERVAL_SECONDS:-300}\"\n11: ZCALL_ENDPOINT=\"${ZCALL_ENDPOINT:-127.0.0.1:8090}\"\n12: export ZCALL_ENDPOINT\n13: \n14: # Legacy binary fallback if zcall routing is unavailable.\n15: GEMMA_BIN=\"${GEMMA_BIN:-/usr/local/bin/op-gemma}\"\n16: \n17: if [ -f /etc/ghostbridge/xray.env ]; then\n18:     . /etc/ghostbridge/xray.env\n19: fi\n20: \n21: derive_and_publish() {\n22:     if command -v zcall >/dev/null 2>&1 \\\n23:         && zcall methods routing 2>/dev/null | grep -q ''^derive''; then\n24:         echo \"routing: zcall derive (registry → D-Bus object)\"\n25:         zcall routing derive -c routing.invoke --arguments ''{}'' || return 1\n26:         echo \"routing: zcall publish (D-Bus → SHM secondary)\"\n27:         zcall routing publish -c routing.invoke --arguments ''{}'' || return 1\n28:         return 0\n29:     fi\n30:     echo \"routing: zcall unavailable — falling back to op-gemma binary\"\n31:     \"$GEMMA_BIN\"\n32: }\n33: \n34: while :; do\n35:     derive_and_publish || echo \"routing: derive/publish failed (will retry)\"\n36: \n37:     \"$SHUTTLE_BIN\" || echo \"routing: shuttle failed (will retry)\"\n38: \n39:     sleep \"$GEMMA_INTERVAL_SECONDS\"\n40: done\n\n(End of file - total 40 lines)\n</content>","title":"deploy/s6/gemma/run","metadata":{"preview":"#!/bin/sh\n# Default routing loop — registry → D-Bus routing plugin → SHM → shuttle.\n# No LLM / xAI. Deterministic fallback when Grok is down or unused.\nexec 2>&1\nset -eu\n\nPATH=\"${PATH:-/usr/local/sbin:/usr/local/bin:/usr/bin:/bin:/home/jeremy/.local/bin}\"\n\nSHUTTLE_BIN=\"${SHUTTLE_BIN:-/usr/local/bin/op-identity-shuttle}\"\nGEMMA_INTERVAL_SECONDS=\"${GEMMA_INTERVAL_SECONDS:-300}\"\nZCALL_ENDPOINT=\"${ZCALL_ENDPOINT:-127.0.0.1:8090}\"\nexport ZCALL_ENDPOINT\n\n# Legacy binary fallback if zcall routing is unavailable.\nGEMMA_BIN=\"${GEMMA_BIN:-/usr/local/bin/op-gemma}\"\n\nif [ -f /etc/ghostbridge/xray.env ]; then\n    . /etc/ghostbridge/xray.env\nfi\n","truncated":false,"loaded":[],"display":{"type":"file","path":"/home/jeremy/git/operation-dbus-proto/deploy/s6/gemma/run","text":"#!/bin/sh\n# Default routing loop — registry → D-Bus routing plugin → SHM → shuttle.\n# No LLM / xAI. Deterministic fallback when Grok is down or unused.\nexec 2>&1\nset -eu\n\nPATH=\"${PATH:-/usr/local/sbin:/usr/local/bin:/usr/bin:/bin:/home/jeremy/.local/bin}\"\n\nSHUTTLE_BIN=\"${SHUTTLE_BIN:-/usr/local/bin/op-identity-shuttle}\"\nGEMMA_INTERVAL_SECONDS=\"${GEMMA_INTERVAL_SECONDS:-300}\"\nZCALL_ENDPOINT=\"${ZCALL_ENDPOINT:-127.0.0.1:8090}\"\nexport ZCALL_ENDPOINT\n\n# Legacy binary fallback if zcall routing is unavailable.\nGEMMA_BIN=\"${GEMMA_BIN:-/usr/local/bin/op-gemma}\"\n\nif [ -f /etc/ghostbridge/xray.env ]; then\n    . /etc/ghostbridge/xray.env\nfi\n\nderive_and_publish() {\n    if command -v zcall >/dev/null 2>&1 \\\n        && zcall methods routing 2>/dev/null | grep -q ''^derive''; then\n        echo \"routing: zcall derive (registry → D-Bus object)\"\n        zcall routing derive -c routing.invoke --arguments ''{}'' || return 1\n        echo \"routing: zcall publish (D-Bus → SHM secondary)\"\n        zcall routing publish -c routing.invoke --arguments ''{}'' || return 1\n        return 0\n    fi\n    echo \"routing: zcall unavailable — falling back to op-gemma binary\"\n    \"$GEMMA_BIN\"\n}\n\nwhile :; do\n    derive_and_publish || echo \"routing: derive/publish failed (will retry)\"\n\n    \"$SHUTTLE_BIN\" || echo \"routing: shuttle failed (will retry)\"\n\n    sleep \"$GEMMA_INTERVAL_SECONDS\"\ndone","lineStart":1,"lineEnd":40,"totalLines":40,"truncated":false}},"time":{"start":1783670371496,"end":1783670371704}}},"time":1783670371704}');
