INSERT INTO event VALUES('evt_f4b0c3897001cYPinVu3tAkpdL','ses_0b516ef36ffeY2Uc26WsdLIdZW',1443,'message.part.updated.1','{"sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","part":{"id":"prt_f4b0c1c5a00172QL0ClV31SWrq","sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","messageID":"msg_f4b0bf1e1001ct2Ea4GVGGrlSU","type":"tool","callID":"call_3347cd33e7b44a84ab3c3e1f","tool":"bash","state":{"status":"running","input":{"command":"# Check what \"ridge header\" and nixtdns means - look at the gbr-xray run script\ncat /etc/s6/sv/gbr-xray/run 2>/dev/null"},"metadata":{"output":"#!/bin/sh\n# gbr-xray - Xray REALITY egress for GhostBridge privacy chain\n\nXRAY_CONFIG=\"${XRAY_CONFIG:-/etc/xray/config.json}\"\n\nif [ ! -f \"$XRAY_CONFIG\" ]; then\n    echo \"Xray config not found: $XRAY_CONFIG\"\n    exit 0\nfi\n\nif [ -f /etc/ghostbridge/xray.env ]; then\n    . /etc/ghostbridge/xray.env\nfi\n\n# Alias 10.0.0.2 on ovsbr0 for Netmaker gRPC bridge\nip addr replace 10.0.0.2/32 dev ovsbr0 2>/dev/null || true\n\nexec 2>&1\nexec /usr/local/bin/xray run -c \"$XRAY_CONFIG\"\n"},"time":{"start":1783670519958}}},"time":1783670519958}');
