INSERT INTO event VALUES('evt_f4b1296360011hKxYao4TYBwYt','ses_0b516ef36ffeY2Uc26WsdLIdZW',1844,'message.part.updated.1','{"sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","part":{"id":"prt_f4b128a7a001dKNtOiuhKXPcF7","sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","messageID":"msg_f4b124bc9001IXN2h4luEzU4Qh","type":"tool","callID":"call_d5afb153e57a4811aad95c21","tool":"bash","state":{"status":"running","input":{"command":"# Check what''s in the broken qdrant dir\nsudo ls -la /var/lib/incus/storage-pools/btrfs-pool/containers/qdrant/ 2>&1\necho \"===\"\n# Check incus storage info for qdrant specifically\nsudo btrfs subvolume show /var/lib/incus/storage-pools/btrfs-pool/containers/qdrant 2>&1\necho \"===\"\n# Check the actual container filesystem path\nsudo ls /var/lib/incus/storage-pools/btrfs-pool/containers/ 2>&1 | head -20\necho \"===\"\n# Which UUID is qdrant? Check incus internal DB\nsudo sqlite3 /var/lib/incus/database/local.db \"SELECT name FROM instances WHERE name=''qdrant'';\" 2>&1\necho \"===\"\n# Check the qdrant storage volume mapping\nsudo sqlite3 /var/lib/incus/database/local.db \"SELECT storage_volumes.name, storage_pools.name FROM storage_volumes JOIN storage_pools ON storage_volumes.storage_pool_id = storage_pools.id WHERE storage_volumes.name=''qdrant'';\" 2>&1"},"metadata":{"output":""},"time":{"start":1783670937141}}},"time":1783670937142}');
