INSERT INTO event VALUES('evt_f4b134822001Vggm8pmSe370cc','ses_0b516ef36ffeY2Uc26WsdLIdZW',1891,'message.part.updated.1','{"sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","part":{"id":"prt_f4b133ef90019p573ahN1m9q8u","sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","messageID":"msg_f4b13058e001xtFvEQz7QsELTC","type":"tool","callID":"call_b8e32e2005dc4366adcc0900","tool":"bash","state":{"status":"running","input":{"command":"# Is qdrant running anywhere on the host?\nps aux | grep -i qdrant 2>&1\necho \"===\"\n# Check s6 for qdrant services\nls /etc/s6/sv/ | grep -i qdrant 2>&1\necho \"===\"\n# Check what port qdrant is expected on\nss -tlnp | grep -E \"6333|6334\" 2>&1\necho \"===\"\n# Check cognitive-mcp config for qdrant endpoint\ngrep -r \"qdrant\" /etc/ghostbridge/ /etc/op-dbus/ /etc/xray/ 2>/dev/null | head -20\necho \"===\"\n# Check incus - is there a qdrant instance at all now?\nincus list | grep -i qdrant 2>&1"},"metadata":{"output":""},"time":{"start":1783670982689}}},"time":1783670982689}');
