INSERT INTO event VALUES('evt_f4b13a28d001QDQPkFcUJizA1o','ses_0b516ef36ffeY2Uc26WsdLIdZW',1924,'message.part.updated.1','{"sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","part":{"id":"prt_f4b13a10a001N9TTVJ9PHf0PhE","sessionID":"ses_0b516ef36ffeY2Uc26WsdLIdZW","messageID":"msg_f4b1374b3001eyH6wLXgE38LiM","type":"tool","callID":"call_fc8c7626edf6453aa4d2d87e","tool":"read","state":{"status":"completed","input":{"filePath":"/home/jeremy/git/operation-dbus-proto/crates/op-cognitive-mcp/src/qdrant_shuttle.rs"},"output":"<path>/home/jeremy/git/operation-dbus-proto/crates/op-cognitive-mcp/src/qdrant_shuttle.rs</path>\n<type>file</type>\n<content>\n1: use std::fs::File;\n2: use std::mem::size_of;\n3: use std::path::{Path, PathBuf};\n4: \n5: use crate::identity_source::active_container_trace_context;\n6: use anyhow::{ensure, Context, Result};\n7: use memmap2::MmapOptions;\n8: use op_identity::IdentitySled;\n9: use op_state_store::{FieldType, PluginSchema};\n10: use qdrant_client::qdrant::{\n11:     Condition, Filter, PointStruct, QueryPointsBuilder, RetrievedPoint, ScoredPoint,\n12:     ScrollPointsBuilder, UpsertPointsBuilder,\n13: };\n14: use qdrant_client::{Payload, Qdrant};\n15: use reqwest::Client;\n16: use serde::Serialize;\n17: use serde_json::Value;\n18: \n19: const DEFAULT_QDRANT_URL: &str = \"http://127.0.0.1:6334\";\n20: const DEFAULT_COLLECTION_NAME: &str = \"ctl_plane_reasoning_episodes\";\n21: const DEFAULT_USER_MEMORY_COLLECTION: &str = \"user_memory\";\n22: const DEFAULT_SCHEMA_SLED_PATH: &str = \"/dev/shm/plugin_schema.dat\";\n23: const DEFAULT_TRACE_LIMIT: u32 = 5;\n24: const DEFAULT_VOYAGE_API_URL: &str = \"https://api.voyageai.com/v1/embeddings\";\n25: const DEFAULT_VOYAGE_MONGODB_API_URL: &str = \"https://ai.mongodb.com/v1/embeddings\";\n26: const DEFAULT_VOYAGE_QUERY_MODEL: &str = \"voyage-4\";\n27: const DEFAULT_VOYAGE_OUTPUT_DIMENSION: u32 = 1024;\n28: \n29: #[derive(Clone, Debug, PartialEq, Eq)]\n30: pub struct SessionTraceContext {\n31:     pub wireguard_pubkey: [u8; 32],\n32:     pub mutation_index: u64,\n33:     pub hashed_footprint: [u8; 32],\n34:     pub trace_id: String,\n35: }\n36: \n37: pub struct QdrantSemanticShuttle {\n38:     client: Qdrant,\n39:     collection_name: String,\n40:     user_memory_collection: String,\n41:     sled_path: PathBuf,\n42:     voyage_client: VoyageClient,\n43: }\n44: \n45: impl QdrantSemanticShuttle {\n46:     /// Initializes the Qdrant gRPC client used by the Accountability Loop.\n47:     pub async fn new() -> Result<Self> {\n48:         let qdrant_url =\n49:             std::env::var(\"COGNITIVE_MCP_QDRANT_URL\").unwrap_or_else(|_| DEFAULT_QDRANT_URL.into());\n50:         let collection_name = std::env::var(\"COGNITIVE_MCP_QDRANT_COLLECTION\")\n51:             .unwrap_or_else(|_| DEFAULT_COLLECTION_NAME.into());\n52:         let user_memory_collection = std::env::var(\"COGNITIVE_MCP_USER_MEMORY_COLLECTION\")\n53:             .unwrap_or_else(|_| DEFAULT_USER_MEMORY_COLLECTION.into());\n54:         let sled_path = std::env::var(\"COGNITIVE_MCP_SCHEMA_SLED_PATH\")\n55:             .unwrap_or_else(|_| DEFAULT_SCHEMA_SLED_PATH.into());\n56:         let voyage_client = VoyageClient::from_env()?;\n57: \n58:         Self::new_with_clients(\n59:             &qdrant_url,\n60:             collection_name,\n61:             user_memory_collection,\n62:             sled_path,\n63:             voyage_client,\n64:         )\n65:         .await\n66:     }\n67: \n68:     async fn new_with_clients(\n69:         qdrant_url: &str,\n70:         collection_name: impl Into<String>,\n71:         user_memory_collection: impl Into<String>,\n72:         sled_path: impl Into<PathBuf>,\n73:         voyage_client: VoyageClient,\n74:     ) -> Result<Self> {\n75:         let collection_name = collection_name.into();\n76:         let user_memory_collection = user_memory_collection.into();\n77:         let sled_path = sled_path.into();\n78:         let client = Qdrant::from_url(qdrant_url)\n79:             .build()\n80:             .with_context(|| format!(\"failed to build Qdrant client for {qdrant_url}\"))?;\n81: \n82:         client.health_check().await.with_context(|| {\n83:             format!(\"failed to reach Qdrant gRPC health endpoint at {qdrant_url}\")\n84:         })?;\n85: \n86:         tracing::info!(\n87:             qdrant_url,\n88:             collection = %collection_name,\n89:             user_memory_collection = %user_memory_collection,\n90:             sled_path = %sled_path.display(),\n91:             \"Qdrant Semantic Shuttle linked to the gRPC interface\"\n92:         );\n93: \n94:         Ok(Self {\n95:             client,\n96:             collection_name,\n97:             user_memory_collection,\n98:             sled_path,\n99:             voyage_client,\n100:         })\n101:     }\n102: \n103:     /// Reads the active identity sled from the schema''d container projection,\n104:     /// falling back to the legacy raw mmap sled when the projection is absent.\n105:     pub fn current_trace_context(&self) -> Result<SessionTraceContext> {\n106:         if let Some(trace) = active_container_trace_context() {\n107:             return Ok(SessionTraceContext {\n108:                 wireguard_pubkey: trace.wireguard_pubkey,\n109:                 mutation_index: trace.mutation_index,\n110:                 hashed_footprint: trace.hashed_footprint,\n111:                 trace_id: trace.trace_id,\n112:             });\n113:         }\n114: \n115:         let sled = read_identity_sled(&self.sled_path)?;\n116:         ensure!(\n117:             sled.is_sled_valid(),\n118:             \"A.N.N.A. Scribe: Invalid Schema State. No active trace available.\"\n119:         );\n120: \n121:         Ok(SessionTraceContext {\n122:             wireguard_pubkey: sled.wireguard_pubkey,\n123:             mutation_index: sled.mutation_index,\n124:             hashed_footprint: sled.hashed_footprint,\n125:             trace_id: format_trace_id(sled.hashed_footprint),\n126:         })\n127:     }\n128: \n129:     /// Renders the active appended PluginSchema into deterministic retrieval text.\n130:     pub fn current_schema_embedding_text(&self) -> Result<String> {\n131:         let schema = read_plugin_schema(&self.sled_path)?;\n132:         Ok(render_schema_embedding_text(&schema))\n133:     }\n134: \n135:     /// Fetches the exact session episodes currently associated with the active trace.\n136:     pub async fn stream_semantic_trace(&self) -> Result<Vec<RetrievedPoint>> {\n137:         self.fetch_trace_episodes(DEFAULT_TRACE_LIMIT).await\n138:     }\n139: \n140:     pub async fn fetch_trace_episodes(&self, limit: u32) -> Result<Vec<RetrievedPoint>> {\n141:         let trace = self.current_trace_context()?;\n142:         let response = self\n143:             .client\n144:             .scroll(\n145:                 ScrollPointsBuilder::new(self.collection_name.clone())\n146:                     .filter(Filter::must([Condition::matches(\n147:                         \"trace_id\",\n148:                         trace.trace_id.clone(),\n149:                     )]))\n150:                     .limit(limit)\n151:                     .with_payload(true)\n152:                     .with_vectors(true),\n153:             )\n154:             .await\n155:             .with_context(|| {\n156:                 format!(\n157:                     \"failed to query Qdrant collection {} for trace {}\",\n158:                     self.collection_name, trace.trace_id\n159:                 )\n160:             })?;\n161: \n162:         tracing::info!(\n163:             trace_id = %trace.trace_id,\n164:             mutation_index = trace.mutation_index,\n165:             matches = response.result.len(),\n166:             \"Accountability Loop fetched semantic trace episodes\"\n167:         );\n168: \n169:         Ok(response.result)\n170:     }\n171: \n172:     /// Performs semantic retrieval within the active trace using a schema-derived Voyage query.\n173:     pub async fn search_semantic_trace(&self, limit: u64) -> Result<Vec<ScoredPoint>> {\n174:         let (trace, schema_query_text) = self.active_schema_query_text()?;\n175:         let limit = if limit == 0 {\n176:             u64::from(DEFAULT_TRACE_LIMIT)\n177:         } else {\n178:             limit\n179:         };\n180: \n181:         let embedding = self\n182:             .voyage_client\n183:             .embed_query(&schema_query_text)\n184:             .await\n185:             .context(\"failed to embed active shared-memory schema with Voyage\")?;\n186: \n187:         let response = self\n188:             .client\n189:             .query(\n190:                 QueryPointsBuilder::new(self.collection_name.clone())\n191:                     .query(embedding)\n192:                     .filter(Filter::must([Condition::matches(\n193:                         \"trace_id\",\n194:                         trace.trace_id.clone(),\n195:                     )]))\n196:                     .limit(limit)\n197:                     .with_payload(true),\n198:             )\n199:             .await\n200:             .with_context(|| {\n201:                 format!(\n202:                     \"failed semantic query against Qdrant collection {} for trace {}\",\n203:                     self.collection_name, trace.trace_id\n204:                 )\n205:             })?;\n206: \n207:         tracing::info!(\n208:             trace_id = %trace.trace_id,\n209:             mutation_index = trace.mutation_index,\n210:             schema_name = %extract_schema_title(&schema_query_text),\n211:             matches = response.result.len(),\n212:             model = %self.voyage_client.model,\n213:             \"Accountability Loop fetched semantic matches from the shared-memory schema projection\"\n214:         );\n215: \n216:         Ok(response.result)\n217:     }\n218: \n219:     // ── User Memory Methods ──────────────────────────────────────────────\n220: \n221:     /// Embed text as a query vector (for semantic search)\n222:     pub async fn embed_query_text(&self, text: &str) -> Result<Vec<f32>> {\n223:         self.voyage_client.embed_query(text).await\n224:     }\n225: \n226:     /// Embed text as a document vector (for storage in Qdrant)\n227:     pub async fn embed_document(&self, text: &str) -> Result<Vec<f32>> {\n228:         self.voyage_client.embed_document(text).await\n229:     }\n230: \n231:     /// Upsert a memory entry into the user_memory collection\n232:     ///\n233:     /// Payload includes `container_id` and `entry_key` for scoped retrieval.\n234:     pub async fn upsert_user_memory(\n235:         &self,\n236:         point_id: impl Into<String>,\n237:         vector: Vec<f32>,\n238:         container_id: &str,\n239:         entry_key: &str,\n240:         content: &str,\n241:     ) -> Result<()> {\n242:         let payload: Payload = serde_json::json!({\n243:             \"container_id\": container_id,\n244:             \"entry_key\": entry_key,\n245:             \"content\": content,\n246:         })\n247:         .try_into()\n248:         .context(\"failed to build user_memory payload\")?;\n249: \n250:         let point = PointStruct::new(point_id.into(), vector, payload);\n251: \n252:         self.client\n253:             .upsert_points(UpsertPointsBuilder::new(\n254:                 self.user_memory_collection.clone(),\n255:                 vec![point],\n256:             ))\n257:             .await\n258:             .with_context(|| {\n259:                 format!(\n260:                     \"failed to upsert user_memory point into collection {}\",\n261:                     self.user_memory_collection\n262:                 )\n263:             })?;\n264: \n265:         tracing::info!(\n266:             collection = %self.user_memory_collection,\n267:             container_id = %container_id,\n268:             entry_key = %entry_key,\n269:             \"User memory upserted to Qdrant\"\n270:         );\n271: \n272:         Ok(())\n273:     }\n274: \n275:     /// Semantic search over user_memory scoped to a container_id\n276:     pub async fn search_user_memory(\n277:         &self,\n278:         query_embedding: Vec<f32>,\n279:         container_id: &str,\n280:         limit: u64,\n281:     ) -> Result<Vec<ScoredPoint>> {\n282:         let response = self\n283:             .client\n284:             .query(\n285:                 QueryPointsBuilder::new(self.user_memory_collection.clone())\n286:                     .query(query_embedding)\n287:                     .filter(Filter::must([Condition::matches(\n288:                         \"container_id\",\n289:                         container_id.to_string(),\n290:                     )]))\n291:                     .limit(limit)\n292:                     .with_payload(true),\n293:             )\n294:             .await\n295:             .with_context(|| {\n296:                 format!(\n297:                     \"failed semantic query against user_memory collection {} for container {}\",\n298:                     self.user_memory_collection, container_id\n299:                 )\n300:             })?;\n301: \n302:         tracing::info!(\n303:             collection = %self.user_memory_collection,\n304:             container_id = %container_id,\n305:             matches = response.result.len(),\n306:             \"User memory semantic search completed\"\n307:         );\n308: \n309:         Ok(response.result)\n310:     }\n311: \n312:     fn active_schema_query_text(&self) -> Result<(SessionTraceContext, String)> {\n313:         let (sled, schema) = read_identity_sled_and_schema(&self.sled_path)?;\n314:         ensure!(\n315:             sled.is_sled_valid(),\n316:             \"A.N.N.A. Scribe: Invalid Schema State. No active trace available.\"\n317:         );\n318: \n319:         Ok((\n320:             SessionTraceContext {\n321:                 wireguard_pubkey: sled.wireguard_pubkey,\n322:                 mutation_index: sled.mutation_index,\n323:                 hashed_footprint: sled.hashed_footprint,\n324:                 trace_id: format_trace_id(sled.hashed_footprint),\n325:             },\n326:             render_schema_embedding_text(&schema),\n327:         ))\n328:     }\n329: }\n330: \n331: struct VoyageClient {\n332:     client: Client,\n333:     api_url: String,\n334:     api_key: String,\n335:     model: String,\n336:     output_dimension: u32,\n337: }\n338: \n339: impl VoyageClient {\n340:     fn from_env() -> Result<Self> {\n341:         let api_key = std::env::var(\"COGNITIVE_MCP_VOYAGE_API_KEY\")\n342:             .or_else(|_| std::env::var(\"VOYAGE_API_KEY\"))\n343:             .or_else(|_| std::env::var(\"VOYAGE_API_KEY_RUST\"))\n344:             .or_else(|_| voyage_key_from_file().ok_or(std::env::VarError::NotPresent))\n345:             .context(\n346:                 \"missing Voyage API key: set COGNITIVE_MCP_VOYAGE_API_KEY, VOYAGE_API_KEY, \\\n347:                  VOYAGE_API_KEY_RUST, or COGNITIVE_MCP_VOYAGE_KEY_FILE\",\n348:             )?;\n349:         let api_url = std::env::var(\"COGNITIVE_MCP_VOYAGE_API_URL\")\n350:             .unwrap_or_else(|_| voyage_url_for_key(&api_key).into());\n351:         let model = std::env::var(\"COGNITIVE_MCP_VOYAGE_QUERY_MODEL\")\n352:             .unwrap_or_else(|_| DEFAULT_VOYAGE_QUERY_MODEL.into());\n353:         let output_dimension = std::env::var(\"COGNITIVE_MCP_VOYAGE_OUTPUT_DIMENSION\")\n354:             .ok()\n355:             .and_then(|value| value.parse::<u32>().ok())\n356:             .unwrap_or(DEFAULT_VOYAGE_OUTPUT_DIMENSION);\n357: \n358:         Ok(Self {\n359:             client: Client::new(),\n360:             api_url,\n361:             api_key,\n362:             model,\n363:             output_dimension,\n364:         })\n365:     }\n366: \n367:     async fn embed_query(&self, input: &str) -> Result<Vec<f32>> {\n368:         self.embed(input, \"query\").await\n369:     }\n370: \n371:     async fn embed_document(&self, input: &str) -> Result<Vec<f32>> {\n372:         self.embed(input, \"document\").await\n373:     }\n374: \n375:     async fn embed(&self, input: &str, input_type: &str) -> Result<Vec<f32>> {\n376:         let body = VoyageEmbeddingRequest {\n377:             input,\n378:             model: &self.model,\n379:             input_type,\n380:             truncation: true,\n381:             output_dimension: self.output_dimension,\n382:             output_dtype: \"float\",\n383:         };\n384: \n385:         let response = self\n386:             .client\n387:             .post(&self.api_url)\n388:             .bearer_auth(&self.api_key)\n389:             .json(&body)\n390:             .send()\n391:             .await\n392:             .with_context(|| format!(\"failed to call Voyage embeddings API at {}\", self.api_url))?\n393:             .error_for_status()\n394:             .context(\"Voyage embeddings API returned an error status\")?;\n395: \n396:         let response_json = response\n397:             .json::<Value>()\n398:             .await\n399:             .context(\"failed to decode Voyage embeddings response\")?;\n400: \n401:         extract_embedding(&response_json)\n402:     }\n403: }\n404: \n405: fn voyage_key_from_file() -> Option<String> {\n406:     let path = std::env::var(\"COGNITIVE_MCP_VOYAGE_KEY_FILE\")\n407:         .ok()\n408:         .map(PathBuf::from)\n409:         .or_else(|| {\n410:             std::env::var_os(\"HOME\").map(|home| Path::new(&home).join(\".ssh/mongo-voyage\"))\n411:         })?;\n412: \n413:     let contents = std::fs::read_to_string(&path).ok()?;\n414:     let key = contents\n415:         .lines()\n416:         .map(str::trim)\n417:         .find(|line| {\n418:             !line.is_empty()\n419:                 && !line.starts_with(''#'')\n420:                 && !line.starts_with(\"mdb_sa_id_\")\n421:                 && !line.starts_with(\"mdb_sa_sk_\")\n422:                 && (line.starts_with(\"al-\") || line.starts_with(\"pa-\"))\n423:         })?\n424:         .to_string();\n425: \n426:     tracing::info!(path = %path.display(), \"Loaded Voyage API key from file\");\n427:     Some(key)\n428: }\n429: \n430: fn voyage_url_for_key(key: &str) -> &''static str {\n431:     if key.trim().starts_with(\"al-\") {\n432:         DEFAULT_VOYAGE_MONGODB_API_URL\n433:     } else {\n434:         DEFAULT_VOYAGE_API_URL\n435:     }\n436: }\n437: \n438: #[derive(Serialize)]\n439: struct VoyageEmbeddingRequest<''a> {\n440:     input: &''a str,\n441:     model: &''a str,\n442:     input_type: &''a str,\n443:     truncation: bool,\n444:     output_dimension: u32,\n445:     output_dtype: &''a str,\n446: }\n447: \n448: fn read_identity_sled(path: &Path) -> Result<IdentitySled> {\n449:     let file = File::open(path)\n450:         .with_context(|| format!(\"failed to open SchemaEngine sled at {}\", path.display()))?;\n451:     // SAFETY: The file is opened read-only and we only read a validated-length region.\n452:     // The mmap is dropped before this function returns, so no dangling pointers escape.\n453:     let mmap = unsafe { MmapOptions::new().map(&file) }\n454:         .with_context(|| format!(\"failed to mmap SchemaEngine sled at {}\", path.display()))?;\n455: \n456:     ensure!(\n457:         mmap.len() >= size_of::<IdentitySled>(),\n458:         \"SchemaEngine sled at {} is smaller than IdentitySled ABI ({})\",\n459:         path.display(),\n460:         size_of::<IdentitySled>()\n461:     );\n462: \n463:     let sled_ptr = mmap.as_ptr().cast::<IdentitySled>();\n464:     // SAFETY: We validated mmap.len() >= size_of::<IdentitySled>() above, so the pointer is\n465:     // within the mapped region. read_unaligned is safe because we only copy the value out.\n466:     let sled = unsafe { std::ptr::read_unaligned(sled_ptr) };\n467: \n468:     Ok(sled)\n469: }\n470: \n471: fn read_plugin_schema(_path: &Path) -> Result<PluginSchema> {\n472:     // The sealed blob IS the plugin: the active session schema is read from\n473:     // the plugin''s own blob in the SHM catalog. `OP_ACTIVE_SCHEMA_PLUGIN`\n474:     // selects which plugin anchors the session''s retrieval text.\n475:     let plugin_id = std::env::var(\"OP_ACTIVE_SCHEMA_PLUGIN\")\n476:         .unwrap_or_else(|_| \"ctl_plane_chatbot\".to_string());\n477:     if let Some(schema) = op_blob::catalog::read_plugin_schema_shm(&plugin_id) {\n478:         return Ok(schema);\n479:     }\n480:     // Transitional fallback: a sled-embedded single schema from hosts not yet\n481:     // re-sealed with a blob catalog.\n482:     let schema_bytes = op_identity::read_schema_blob().with_context(|| {\n483:         format!(\"no sealed blob for ''{plugin_id}'' and no sled-embedded schema available\")\n484:     })?;\n485:     parse_plugin_schema(schema_bytes, Path::new(\"(sled-embedded schema blob)\"))\n486: }\n487: \n488: fn read_identity_sled_and_schema(path: &Path) -> Result<(IdentitySled, PluginSchema)> {\n489:     let sled = read_identity_sled(path)?;\n490:     let schema = read_plugin_schema(path)?;\n491:     Ok((sled, schema))\n492: }\n493: \n494: fn parse_plugin_schema(schema_bytes: Vec<u8>, path: &Path) -> Result<PluginSchema> {\n495:     ensure!(\n496:         !schema_bytes.is_empty(),\n497:         \"Schema file at {} is empty\",\n498:         path.display()\n499:     );\n500: \n501:     serde_json::from_slice(&schema_bytes)\n502:         .with_context(|| format!(\"failed to parse PluginSchema from {}\", path.display()))\n503: }\n504: \n505: fn format_trace_id(hashed_footprint: [u8; 32]) -> String {\n506:     format!(\"trace-{}\", hex::encode(hashed_footprint))\n507: }\n508: \n509: fn render_schema_embedding_text(schema: &PluginSchema) -> String {\n510:     let mut lines = vec![\n511:         format!(\"schema_name: {}\", schema.name),\n512:         format!(\"schema_category: {}\", schema.category),\n513:         format!(\"schema_version: {}\", schema.version),\n514:         format!(\"schema_description: {}\", schema.description.trim()),\n515:     ];\n516: \n517:     let mut tags = schema.tags.clone();\n518:     tags.sort();\n519:     if !tags.is_empty() {\n520:         lines.push(format!(\"schema_tags: {}\", tags.join(\", \")));\n521:     }\n522: \n523:     let mut immutable_paths = schema.immutable_paths.clone();\n524:     immutable_paths.sort();\n525:     if !immutable_paths.is_empty() {\n526:         lines.push(format!(\"immutable_paths: {}\", immutable_paths.join(\", \")));\n527:     }\n528: \n529:     let mut dependencies = schema.dependencies.clone();\n530:     dependencies.sort();\n531:     if !dependencies.is_empty() {\n532:         lines.push(format!(\"dependencies: {}\", dependencies.join(\", \")));\n533:     }\n534: \n535:     let mut field_names = schema.fields.keys().cloned().collect::<Vec<_>>();\n536:     field_names.sort();\n537: \n538:     for field_name in field_names {\n539:         let Some(field_schema) = schema.fields.get(&field_name) else {\n540:             continue;\n541:         };\n542: \n543:         lines.push(format!(\n544:             \"field {}: type={}, required={}, read_only={}, description={}\",\n545:             field_name,\n546:             render_field_type(&field_schema.field_type),\n547:             field_schema.required,\n548:             field_schema.read_only,\n549:             field_schema.description.trim()\n550:         ));\n551: \n552:         if let Some(condition) = &field_schema.read_only_when {\n553:             lines.push(format!(\n554:                 \"field {} read_only_when: {}={}\",\n555:                 field_name, condition.property, condition.value\n556:             ));\n557:         }\n558: \n559:         if !field_schema.constraints.is_empty() {\n560:             let constraints = field_schema\n561:                 .constraints\n562:                 .iter()\n563:                 .map(render_constraint)\n564:                 .collect::<Vec<_>>()\n565:                 .join(\", \");\n566:             lines.push(format!(\"field {} constraints: {}\", field_name, constraints));\n567:         }\n568:     }\n569: \n570:     lines.join(\"\\n\")\n571: }\n572: \n573: fn render_field_type(field_type: &FieldType) -> String {\n574:     match field_type {\n575:         FieldType::String => \"string\".to_string(),\n576:         FieldType::Integer => \"integer\".to_string(),\n577:         FieldType::Float => \"float\".to_string(),\n578:         FieldType::Boolean => \"boolean\".to_string(),\n579:         FieldType::Array(inner) => format!(\"array<{}>\", render_field_type(inner)),\n580:         FieldType::Object(fields) => {\n581:             let mut names = fields.keys().cloned().collect::<Vec<_>>();\n582:             names.sort();\n583:             format!(\"object<{}>\", names.join(\"|\"))\n584:         }\n585:         FieldType::Enum(values) => format!(\"enum<{}>\", values.join(\"|\")),\n586:         FieldType::OneOf(branches) => format!(\n587:             \"one_of<{}>\",\n588:             branches\n589:                 .iter()\n590:                 .map(render_field_type)\n591:                 .collect::<Vec<_>>()\n592:                 .join(\"|\")\n593:         ),\n594:         FieldType::Any => \"any\".to_string(),\n595:     }\n596: }\n597: \n598: fn render_constraint(constraint: &op_state_store::Constraint) -> String {\n599:     match constraint {\n600:         op_state_store::Constraint::Min { value } => format!(\"min={value}\"),\n601:         op_state_store::Constraint::Max { value } => format!(\"max={value}\"),\n602:         op_state_store::Constraint::Pattern { regex } => format!(\"pattern={regex}\"),\n603:         op_state_store::Constraint::OneOf { values } => {\n604:             format!(\n605:                 \"one_of={}\",\n606:                 serde_json::to_string(values).unwrap_or_default()\n607:             )\n608:         }\n609:         op_state_store::Constraint::RequiresField { field } => format!(\"requires_field={field}\"),\n610:         op_state_store::Constraint::Custom { validator } => format!(\"custom={validator}\"),\n611:     }\n612: }\n613: \n614: fn extract_schema_title(schema_query_text: &str) -> &str {\n615:     schema_query_text\n616:         .lines()\n617:         .find_map(|line| line.strip_prefix(\"schema_name: \"))\n618:         .unwrap_or(\"unknown\")\n619: }\n620: \n621: fn extract_embedding(response_json: &Value) -> Result<Vec<f32>> {\n622:     let Some(embedding_values) = response_json\n623:         .get(\"data\")\n624:         .and_then(Value::as_array)\n625:         .and_then(|entries| entries.first())\n626:         .and_then(|entry| entry.get(\"embedding\"))\n627:         .and_then(Value::as_array)\n628:         .or_else(|| {\n629:             response_json\n630:                 .get(\"embeddings\")\n631:                 .and_then(Value::as_array)\n632:                 .and_then(|entries| entries.first())\n633:                 .and_then(Value::as_array)\n634:         })\n635:     else {\n636:         return Err(anyhow::anyhow!(\n637:             \"Voyage embeddings response did not contain a usable embedding\"\n638:         ));\n639:     };\n640: \n641:     let mut embedding = Vec::with_capacity(embedding_values.len());\n642:     for value in embedding_values {\n643:         let number = value\n644:             .as_f64()\n645:             .context(\"Voyage embedding contained a non-numeric value\")?;\n646:         embedding.push(number as f32);\n647:     }\n648: \n649:     ensure!(!embedding.is_empty(), \"Voyage embedding response was empty\");\n650:     Ok(embedding)\n651: }\n652: \n653: #[cfg(test)]\n654: mod tests {\n655:     use super::*;\n656:     use op_state_store::{Constraint, FieldSchema, ReadOnlyCondition};\n657:     use serde_json::json;\n658:     use std::collections::HashMap;\n659: \n660:     #[test]\n661:     fn should_preserve_identity_sled_abi_shape() {\n662:         // Canonical sled from op-identity: wireguard_pubkey(32) + mutation_index(8)\n663:         // + is_valid(1) + _pad(7) + hashed_footprint(32) + subid taxonomy + compliance fields.\n664:         assert!(\n665:             size_of::<IdentitySled>() >= 32 + 8 + 1 + 7 + 32,\n666:             \"IdentitySled ABI unexpectedly shrank (using canonical op-identity layout)\"\n667:         );\n668:     }\n669: \n670:     #[test]\n671:     fn should_format_trace_id_from_hashed_footprint() {\n672:         let trace_id = format_trace_id([0xAB; 32]);\n673:         assert_eq!(trace_id, format!(\"trace-{}\", \"ab\".repeat(32)));\n674:     }\n675: \n676:     #[test]\n677:     fn should_extract_embedding_from_openai_style_data_payload() {\n678:         let embedding = extract_embedding(&json!({\n679:             \"data\": [{\n680:                 \"embedding\": [0.25, -0.5, 1.5]\n681:             }]\n682:         }))\n683:         .unwrap();\n684: \n685:         assert_eq!(embedding, vec![0.25, -0.5, 1.5]);\n686:     }\n687: \n688:     #[test]\n689:     fn should_extract_embedding_from_embeddings_array_payload() {\n690:         let embedding = extract_embedding(&json!({\n691:             \"embeddings\": [[0.1, 0.2, 0.3]]\n692:         }))\n693:         .unwrap();\n694: \n695:         assert_eq!(embedding, vec![0.1, 0.2, 0.3]);\n696:     }\n697: \n698:     #[test]\n699:     fn should_render_schema_embedding_text_deterministically() {\n700:         let mut nested_fields = HashMap::new();\n701:         nested_fields.insert(\n702:             \"beta\".to_string(),\n703:             FieldSchema {\n704:                 field_type: FieldType::Boolean,\n705:                 required: false,\n706:                 description: String::new(),\n707:                 default: None,\n708:                 example: None,\n709:                 constraints: vec![],\n710:                 read_only: false,\n711:                 read_only_when: None,\n712:             },\n713:         );\n714:         nested_fields.insert(\n715:             \"alpha\".to_string(),\n716:             FieldSchema {\n717:                 field_type: FieldType::String,\n718:                 required: false,\n719:                 description: String::new(),\n720:                 default: None,\n721:                 example: None,\n722:                 constraints: vec![],\n723:                 read_only: false,\n724:                 read_only_when: None,\n725:             },\n726:         );\n727: \n728:         let mut fields = HashMap::new();\n729:         fields.insert(\n730:             \"outcome_class\".to_string(),\n731:             FieldSchema {\n732:                 field_type: FieldType::Enum(vec![\"deny\".into(), \"allow\".into()]),\n733:                 required: true,\n734:                 description: \"Outcome bucket\".into(),\n735:                 default: None,\n736:                 example: None,\n737:                 constraints: vec![Constraint::OneOf {\n738:                     values: vec![simd_json::json!(\"allow\"), simd_json::json!(\"deny\")],\n739:                 }],\n740:                 read_only: false,\n741:                 read_only_when: Some(ReadOnlyCondition {\n742:                     property: \"sealed\".into(),\n743:                     value: \"true\".into(),\n744:                 }),\n745:             },\n746:         );\n747:         fields.insert(\n748:             \"tools_consulted\".to_string(),\n749:             FieldSchema {\n750:                 field_type: FieldType::Array(Box::new(FieldType::Object(nested_fields))),\n751:                 required: false,\n752:                 description: \"Tools touched by the episode\".into(),\n753:                 default: None,\n754:                 example: None,\n755:                 constraints: vec![Constraint::Min { value: 1.0 }],\n756:                 read_only: true,\n757:                 read_only_when: None,\n758:             },\n759:         );\n760: \n761:         let schema = PluginSchema {\n762:             name: \"ctl-plane-chatbot\".into(),\n763:             category: \"accountability\".into(),\n764:             version: \"1.0.0\".into(),\n765:             description: \"Human reviewable reasoning episodes\".into(),\n766:             display_name: None,\n767:             fields,\n768:             dependencies: vec![\"op-grpc-bridge\".into(), \"op-state-store\".into()],\n769:             example: None,\n770:             immutable_paths: vec![\"/episode_id\".into()],\n771:             tags: vec![\"audit\".into(), \"pii\".into()],\n772:             dialect: op_state_store::DEFAULT_SCHEMA_DIALECT.into(),\n773:             mutation_index: Some(7),\n774:             subids: std::collections::HashMap::new(),\n775:             methods: std::collections::HashMap::new(),\n776:             signals: vec![],\n777:             guarantees: op_state_store::PluginCapabilities::default(),\n778:         };\n779: \n780:         let rendered = render_schema_embedding_text(&schema);\n781: \n782:         assert!(rendered.contains(\"schema_name: ctl-plane-chatbot\"));\n783:         assert!(rendered.contains(\"schema_category: accountability\"));\n784:         assert!(rendered.contains(\"schema_tags: audit, pii\"));\n785:         assert!(rendered.contains(\"immutable_paths: /episode_id\"));\n786:         assert!(rendered.contains(\"dependencies: op-grpc-bridge, op-state-store\"));\n787:         assert!(rendered.contains(\n788:             \"field outcome_class: type=enum<deny|allow>, required=true, read_only=false, description=Outcome bucket\"\n789:         ));\n790:         assert!(rendered.contains(\"field outcome_class read_only_when: sealed=true\"));\n791:         assert!(rendered.contains(\"field tools_consulted: type=array<object<alpha|beta>>\"));\n792:     }\n793: }\n\n(End of file - total 793 lines)\n</content>","title":"crates/op-cognitive-mcp/src/qdrant_shuttle.rs","metadata":{"preview":"use std::fs::File;\nuse std::mem::size_of;\nuse std::path::{Path, PathBuf};\n\nuse crate::identity_source::active_container_trace_context;\nuse anyhow::{ensure, Context, Result};\nuse memmap2::MmapOptions;\nuse op_identity::IdentitySled;\nuse op_state_store::{FieldType, PluginSchema};\nuse qdrant_client::qdrant::{\n    Condition, Filter, PointStruct, QueryPointsBuilder, RetrievedPoint, ScoredPoint,\n    ScrollPointsBuilder, UpsertPointsBuilder,\n};\nuse qdrant_client::{Payload, Qdrant};\nuse reqwest::Client;\nuse serde::Serialize;\nuse serde_json::Value;\n\nconst DEFAULT_QDRANT_URL: &str = \"http://127.0.0.1:6334\";\nconst DEFAULT_COLLECTION_NAME: &str = \"ctl_plane_reasoning_episodes\";","truncated":false,"loaded":[],"display":{"type":"file","path":"/home/jeremy/git/operation-dbus-proto/crates/op-cognitive-mcp/src/qdrant_shuttle.rs","text":"use std::fs::File;\nuse std::mem::size_of;\nuse std::path::{Path, PathBuf};\n\nuse crate::identity_source::active_container_trace_context;\nuse anyhow::{ensure, Context, Result};\nuse memmap2::MmapOptions;\nuse op_identity::IdentitySled;\nuse op_state_store::{FieldType, PluginSchema};\nuse qdrant_client::qdrant::{\n    Condition, Filter, PointStruct, QueryPointsBuilder, RetrievedPoint, ScoredPoint,\n    ScrollPointsBuilder, UpsertPointsBuilder,\n};\nuse qdrant_client::{Payload, Qdrant};\nuse reqwest::Client;\nuse serde::Serialize;\nuse serde_json::Value;\n\nconst DEFAULT_QDRANT_URL: &str = \"http://127.0.0.1:6334\";\nconst DEFAULT_COLLECTION_NAME: &str = \"ctl_plane_reasoning_episodes\";\nconst DEFAULT_USER_MEMORY_COLLECTION: &str = \"user_memory\";\nconst DEFAULT_SCHEMA_SLED_PATH: &str = \"/dev/shm/plugin_schema.dat\";\nconst DEFAULT_TRACE_LIMIT: u32 = 5;\nconst DEFAULT_VOYAGE_API_URL: &str = \"https://api.voyageai.com/v1/embeddings\";\nconst DEFAULT_VOYAGE_MONGODB_API_URL: &str = \"https://ai.mongodb.com/v1/embeddings\";\nconst DEFAULT_VOYAGE_QUERY_MODEL: &str = \"voyage-4\";\nconst DEFAULT_VOYAGE_OUTPUT_DIMENSION: u32 = 1024;\n\n#[derive(Clone, Debug, PartialEq, Eq)]\npub struct SessionTraceContext {\n    pub wireguard_pubkey: [u8; 32],\n    pub mutation_index: u64,\n    pub hashed_footprint: [u8; 32],\n    pub trace_id: String,\n}\n\npub struct QdrantSemanticShuttle {\n    client: Qdrant,\n    collection_name: String,\n    user_memory_collection: String,\n    sled_path: PathBuf,\n    voyage_client: VoyageClient,\n}\n\nimpl QdrantSemanticShuttle {\n    /// Initializes the Qdrant gRPC client used by the Accountability Loop.\n    pub async fn new() -> Result<Self> {\n        let qdrant_url =\n            std::env::var(\"COGNITIVE_MCP_QDRANT_URL\").unwrap_or_else(|_| DEFAULT_QDRANT_URL.into());\n        let collection_name = std::env::var(\"COGNITIVE_MCP_QDRANT_COLLECTION\")\n            .unwrap_or_else(|_| DEFAULT_COLLECTION_NAME.into());\n        let user_memory_collection = std::env::var(\"COGNITIVE_MCP_USER_MEMORY_COLLECTION\")\n            .unwrap_or_else(|_| DEFAULT_USER_MEMORY_COLLECTION.into());\n        let sled_path = std::env::var(\"COGNITIVE_MCP_SCHEMA_SLED_PATH\")\n            .unwrap_or_else(|_| DEFAULT_SCHEMA_SLED_PATH.into());\n        let voyage_client = VoyageClient::from_env()?;\n\n        Self::new_with_clients(\n            &qdrant_url,\n            collection_name,\n            user_memory_collection,\n            sled_path,\n            voyage_client,\n        )\n        .await\n    }\n\n    async fn new_with_clients(\n        qdrant_url: &str,\n        collection_name: impl Into<String>,\n        user_memory_collection: impl Into<String>,\n        sled_path: impl Into<PathBuf>,\n        voyage_client: VoyageClient,\n    ) -> Result<Self> {\n        let collection_name = collection_name.into();\n        let user_memory_collection = user_memory_collection.into();\n        let sled_path = sled_path.into();\n        let client = Qdrant::from_url(qdrant_url)\n            .build()\n            .with_context(|| format!(\"failed to build Qdrant client for {qdrant_url}\"))?;\n\n        client.health_check().await.with_context(|| {\n            format!(\"failed to reach Qdrant gRPC health endpoint at {qdrant_url}\")\n        })?;\n\n        tracing::info!(\n            qdrant_url,\n            collection = %collection_name,\n            user_memory_collection = %user_memory_collection,\n            sled_path = %sled_path.display(),\n            \"Qdrant Semantic Shuttle linked to the gRPC interface\"\n        );\n\n        Ok(Self {\n            client,\n            collection_name,\n            user_memory_collection,\n            sled_path,\n            voyage_client,\n        })\n    }\n\n    /// Reads the active identity sled from the schema''d container projection,\n    /// falling back to the legacy raw mmap sled when the projection is absent.\n    pub fn current_trace_context(&self) -> Result<SessionTraceContext> {\n        if let Some(trace) = active_container_trace_context() {\n            return Ok(SessionTraceContext {\n                wireguard_pubkey: trace.wireguard_pubkey,\n                mutation_index: trace.mutation_index,\n                hashed_footprint: trace.hashed_footprint,\n                trace_id: trace.trace_id,\n            });\n        }\n\n        let sled = read_identity_sled(&self.sled_path)?;\n        ensure!(\n            sled.is_sled_valid(),\n            \"A.N.N.A. Scribe: Invalid Schema State. No active trace available.\"\n        );\n\n        Ok(SessionTraceContext {\n            wireguard_pubkey: sled.wireguard_pubkey,\n            mutation_index: sled.mutation_index,\n            hashed_footprint: sled.hashed_footprint,\n            trace_id: format_trace_id(sled.hashed_footprint),\n        })\n    }\n\n    /// Renders the active appended PluginSchema into deterministic retrieval text.\n    pub fn current_schema_embedding_text(&self) -> Result<String> {\n        let schema = read_plugin_schema(&self.sled_path)?;\n        Ok(render_schema_embedding_text(&schema))\n    }\n\n    /// Fetches the exact session episodes currently associated with the active trace.\n    pub async fn stream_semantic_trace(&self) -> Result<Vec<RetrievedPoint>> {\n        self.fetch_trace_episodes(DEFAULT_TRACE_LIMIT).await\n    }\n\n    pub async fn fetch_trace_episodes(&self, limit: u32) -> Result<Vec<RetrievedPoint>> {\n        let trace = self.current_trace_context()?;\n        let response = self\n            .client\n            .scroll(\n                ScrollPointsBuilder::new(self.collection_name.clone())\n                    .filter(Filter::must([Condition::matches(\n                        \"trace_id\",\n                        trace.trace_id.clone(),\n                    )]))\n                    .limit(limit)\n                    .with_payload(true)\n                    .with_vectors(true),\n            )\n            .await\n            .with_context(|| {\n                format!(\n                    \"failed to query Qdrant collection {} for trace {}\",\n                    self.collection_name, trace.trace_id\n                )\n            })?;\n\n        tracing::info!(\n            trace_id = %trace.trace_id,\n            mutation_index = trace.mutation_index,\n            matches = response.result.len(),\n            \"Accountability Loop fetched semantic trace episodes\"\n        );\n\n        Ok(response.result)\n    }\n\n    /// Performs semantic retrieval within the active trace using a schema-derived Voyage query.\n    pub async fn search_semantic_trace(&self, limit: u64) -> Result<Vec<ScoredPoint>> {\n        let (trace, schema_query_text) = self.active_schema_query_text()?;\n        let limit = if limit == 0 {\n            u64::from(DEFAULT_TRACE_LIMIT)\n        } else {\n            limit\n        };\n\n        let embedding = self\n            .voyage_client\n            .embed_query(&schema_query_text)\n            .await\n            .context(\"failed to embed active shared-memory schema with Voyage\")?;\n\n        let response = self\n            .client\n            .query(\n                QueryPointsBuilder::new(self.collection_name.clone())\n                    .query(embedding)\n                    .filter(Filter::must([Condition::matches(\n                        \"trace_id\",\n                        trace.trace_id.clone(),\n                    )]))\n                    .limit(limit)\n                    .with_payload(true),\n            )\n            .await\n            .with_context(|| {\n                format!(\n                    \"failed semantic query against Qdrant collection {} for trace {}\",\n                    self.collection_name, trace.trace_id\n                )\n            })?;\n\n        tracing::info!(\n            trace_id = %trace.trace_id,\n            mutation_index = trace.mutation_index,\n            schema_name = %extract_schema_title(&schema_query_text),\n            matches = response.result.len(),\n            model = %self.voyage_client.model,\n            \"Accountability Loop fetched semantic matches from the shared-memory schema projection\"\n        );\n\n        Ok(response.result)\n    }\n\n    // ── User Memory Methods ──────────────────────────────────────────────\n\n    /// Embed text as a query vector (for semantic search)\n    pub async fn embed_query_text(&self, text: &str) -> Result<Vec<f32>> {\n        self.voyage_client.embed_query(text).await\n    }\n\n    /// Embed text as a document vector (for storage in Qdrant)\n    pub async fn embed_document(&self, text: &str) -> Result<Vec<f32>> {\n        self.voyage_client.embed_document(text).await\n    }\n\n    /// Upsert a memory entry into the user_memory collection\n    ///\n    /// Payload includes `container_id` and `entry_key` for scoped retrieval.\n    pub async fn upsert_user_memory(\n        &self,\n        point_id: impl Into<String>,\n        vector: Vec<f32>,\n        container_id: &str,\n        entry_key: &str,\n        content: &str,\n    ) -> Result<()> {\n        let payload: Payload = serde_json::json!({\n            \"container_id\": container_id,\n            \"entry_key\": entry_key,\n            \"content\": content,\n        })\n        .try_into()\n        .context(\"failed to build user_memory payload\")?;\n\n        let point = PointStruct::new(point_id.into(), vector, payload);\n\n        self.client\n            .upsert_points(UpsertPointsBuilder::new(\n                self.user_memory_collection.clone(),\n                vec![point],\n            ))\n            .await\n            .with_context(|| {\n                format!(\n                    \"failed to upsert user_memory point into collection {}\",\n                    self.user_memory_collection\n                )\n            })?;\n\n        tracing::info!(\n            collection = %self.user_memory_collection,\n            container_id = %container_id,\n            entry_key = %entry_key,\n            \"User memory upserted to Qdrant\"\n        );\n\n        Ok(())\n    }\n\n    /// Semantic search over user_memory scoped to a container_id\n    pub async fn search_user_memory(\n        &self,\n        query_embedding: Vec<f32>,\n        container_id: &str,\n        limit: u64,\n    ) -> Result<Vec<ScoredPoint>> {\n        let response = self\n            .client\n            .query(\n                QueryPointsBuilder::new(self.user_memory_collection.clone())\n                    .query(query_embedding)\n                    .filter(Filter::must([Condition::matches(\n                        \"container_id\",\n                        container_id.to_string(),\n                    )]))\n                    .limit(limit)\n                    .with_payload(true),\n            )\n            .await\n            .with_context(|| {\n                format!(\n                    \"failed semantic query against user_memory collection {} for container {}\",\n                    self.user_memory_collection, container_id\n                )\n            })?;\n\n        tracing::info!(\n            collection = %self.user_memory_collection,\n            container_id = %container_id,\n            matches = response.result.len(),\n            \"User memory semantic search completed\"\n        );\n\n        Ok(response.result)\n    }\n\n    fn active_schema_query_text(&self) -> Result<(SessionTraceContext, String)> {\n        let (sled, schema) = read_identity_sled_and_schema(&self.sled_path)?;\n        ensure!(\n            sled.is_sled_valid(),\n            \"A.N.N.A. Scribe: Invalid Schema State. No active trace available.\"\n        );\n\n        Ok((\n            SessionTraceContext {\n                wireguard_pubkey: sled.wireguard_pubkey,\n                mutation_index: sled.mutation_index,\n                hashed_footprint: sled.hashed_footprint,\n                trace_id: format_trace_id(sled.hashed_footprint),\n            },\n            render_schema_embedding_text(&schema),\n        ))\n    }\n}\n\nstruct VoyageClient {\n    client: Client,\n    api_url: String,\n    api_key: String,\n    model: String,\n    output_dimension: u32,\n}\n\nimpl VoyageClient {\n    fn from_env() -> Result<Self> {\n        let api_key = std::env::var(\"COGNITIVE_MCP_VOYAGE_API_KEY\")\n            .or_else(|_| std::env::var(\"VOYAGE_API_KEY\"))\n            .or_else(|_| std::env::var(\"VOYAGE_API_KEY_RUST\"))\n            .or_else(|_| voyage_key_from_file().ok_or(std::env::VarError::NotPresent))\n            .context(\n                \"missing Voyage API key: set COGNITIVE_MCP_VOYAGE_API_KEY, VOYAGE_API_KEY, \\\n                 VOYAGE_API_KEY_RUST, or COGNITIVE_MCP_VOYAGE_KEY_FILE\",\n            )?;\n        let api_url = std::env::var(\"COGNITIVE_MCP_VOYAGE_API_URL\")\n            .unwrap_or_else(|_| voyage_url_for_key(&api_key).into());\n        let model = std::env::var(\"COGNITIVE_MCP_VOYAGE_QUERY_MODEL\")\n            .unwrap_or_else(|_| DEFAULT_VOYAGE_QUERY_MODEL.into());\n        let output_dimension = std::env::var(\"COGNITIVE_MCP_VOYAGE_OUTPUT_DIMENSION\")\n            .ok()\n            .and_then(|value| value.parse::<u32>().ok())\n            .unwrap_or(DEFAULT_VOYAGE_OUTPUT_DIMENSION);\n\n        Ok(Self {\n            client: Client::new(),\n            api_url,\n            api_key,\n            model,\n            output_dimension,\n        })\n    }\n\n    async fn embed_query(&self, input: &str) -> Result<Vec<f32>> {\n        self.embed(input, \"query\").await\n    }\n\n    async fn embed_document(&self, input: &str) -> Result<Vec<f32>> {\n        self.embed(input, \"document\").await\n    }\n\n    async fn embed(&self, input: &str, input_type: &str) -> Result<Vec<f32>> {\n        let body = VoyageEmbeddingRequest {\n            input,\n            model: &self.model,\n            input_type,\n            truncation: true,\n            output_dimension: self.output_dimension,\n            output_dtype: \"float\",\n        };\n\n        let response = self\n            .client\n            .post(&self.api_url)\n            .bearer_auth(&self.api_key)\n            .json(&body)\n            .send()\n            .await\n            .with_context(|| format!(\"failed to call Voyage embeddings API at {}\", self.api_url))?\n            .error_for_status()\n            .context(\"Voyage embeddings API returned an error status\")?;\n\n        let response_json = response\n            .json::<Value>()\n            .await\n            .context(\"failed to decode Voyage embeddings response\")?;\n\n        extract_embedding(&response_json)\n    }\n}\n\nfn voyage_key_from_file() -> Option<String> {\n    let path = std::env::var(\"COGNITIVE_MCP_VOYAGE_KEY_FILE\")\n        .ok()\n        .map(PathBuf::from)\n        .or_else(|| {\n            std::env::var_os(\"HOME\").map(|home| Path::new(&home).join(\".ssh/mongo-voyage\"))\n        })?;\n\n    let contents = std::fs::read_to_string(&path).ok()?;\n    let key = contents\n        .lines()\n        .map(str::trim)\n        .find(|line| {\n            !line.is_empty()\n                && !line.starts_with(''#'')\n                && !line.starts_with(\"mdb_sa_id_\")\n                && !line.starts_with(\"mdb_sa_sk_\")\n                && (line.starts_with(\"al-\") || line.starts_with(\"pa-\"))\n        })?\n        .to_string();\n\n    tracing::info!(path = %path.display(), \"Loaded Voyage API key from file\");\n    Some(key)\n}\n\nfn voyage_url_for_key(key: &str) -> &''static str {\n    if key.trim().starts_with(\"al-\") {\n        DEFAULT_VOYAGE_MONGODB_API_URL\n    } else {\n        DEFAULT_VOYAGE_API_URL\n    }\n}\n\n#[derive(Serialize)]\nstruct VoyageEmbeddingRequest<''a> {\n    input: &''a str,\n    model: &''a str,\n    input_type: &''a str,\n    truncation: bool,\n    output_dimension: u32,\n    output_dtype: &''a str,\n}\n\nfn read_identity_sled(path: &Path) -> Result<IdentitySled> {\n    let file = File::open(path)\n        .with_context(|| format!(\"failed to open SchemaEngine sled at {}\", path.display()))?;\n    // SAFETY: The file is opened read-only and we only read a validated-length region.\n    // The mmap is dropped before this function returns, so no dangling pointers escape.\n    let mmap = unsafe { MmapOptions::new().map(&file) }\n        .with_context(|| format!(\"failed to mmap SchemaEngine sled at {}\", path.display()))?;\n\n    ensure!(\n        mmap.len() >= size_of::<IdentitySled>(),\n        \"SchemaEngine sled at {} is smaller than IdentitySled ABI ({})\",\n        path.display(),\n        size_of::<IdentitySled>()\n    );\n\n    let sled_ptr = mmap.as_ptr().cast::<IdentitySled>();\n    // SAFETY: We validated mmap.len() >= size_of::<IdentitySled>() above, so the pointer is\n    // within the mapped region. read_unaligned is safe because we only copy the value out.\n    let sled = unsafe { std::ptr::read_unaligned(sled_ptr) };\n\n    Ok(sled)\n}\n\nfn read_plugin_schema(_path: &Path) -> Result<PluginSchema> {\n    // The sealed blob IS the plugin: the active session schema is read from\n    // the plugin''s own blob in the SHM catalog. `OP_ACTIVE_SCHEMA_PLUGIN`\n    // selects which plugin anchors the session''s retrieval text.\n    let plugin_id = std::env::var(\"OP_ACTIVE_SCHEMA_PLUGIN\")\n        .unwrap_or_else(|_| \"ctl_plane_chatbot\".to_string());\n    if let Some(schema) = op_blob::catalog::read_plugin_schema_shm(&plugin_id) {\n        return Ok(schema);\n    }\n    // Transitional fallback: a sled-embedded single schema from hosts not yet\n    // re-sealed with a blob catalog.\n    let schema_bytes = op_identity::read_schema_blob().with_context(|| {\n        format!(\"no sealed blob for ''{plugin_id}'' and no sled-embedded schema available\")\n    })?;\n    parse_plugin_schema(schema_bytes, Path::new(\"(sled-embedded schema blob)\"))\n}\n\nfn read_identity_sled_and_schema(path: &Path) -> Result<(IdentitySled, PluginSchema)> {\n    let sled = read_identity_sled(path)?;\n    let schema = read_plugin_schema(path)?;\n    Ok((sled, schema))\n}\n\nfn parse_plugin_schema(schema_bytes: Vec<u8>, path: &Path) -> Result<PluginSchema> {\n    ensure!(\n        !schema_bytes.is_empty(),\n        \"Schema file at {} is empty\",\n        path.display()\n    );\n\n    serde_json::from_slice(&schema_bytes)\n        .with_context(|| format!(\"failed to parse PluginSchema from {}\", path.display()))\n}\n\nfn format_trace_id(hashed_footprint: [u8; 32]) -> String {\n    format!(\"trace-{}\", hex::encode(hashed_footprint))\n}\n\nfn render_schema_embedding_text(schema: &PluginSchema) -> String {\n    let mut lines = vec![\n        format!(\"schema_name: {}\", schema.name),\n        format!(\"schema_category: {}\", schema.category),\n        format!(\"schema_version: {}\", schema.version),\n        format!(\"schema_description: {}\", schema.description.trim()),\n    ];\n\n    let mut tags = schema.tags.clone();\n    tags.sort();\n    if !tags.is_empty() {\n        lines.push(format!(\"schema_tags: {}\", tags.join(\", \")));\n    }\n\n    let mut immutable_paths = schema.immutable_paths.clone();\n    immutable_paths.sort();\n    if !immutable_paths.is_empty() {\n        lines.push(format!(\"immutable_paths: {}\", immutable_paths.join(\", \")));\n    }\n\n    let mut dependencies = schema.dependencies.clone();\n    dependencies.sort();\n    if !dependencies.is_empty() {\n        lines.push(format!(\"dependencies: {}\", dependencies.join(\", \")));\n    }\n\n    let mut field_names = schema.fields.keys().cloned().collect::<Vec<_>>();\n    field_names.sort();\n\n    for field_name in field_names {\n        let Some(field_schema) = schema.fields.get(&field_name) else {\n            continue;\n        };\n\n        lines.push(format!(\n            \"field {}: type={}, required={}, read_only={}, description={}\",\n            field_name,\n            render_field_type(&field_schema.field_type),\n            field_schema.required,\n            field_schema.read_only,\n            field_schema.description.trim()\n        ));\n\n        if let Some(condition) = &field_schema.read_only_when {\n            lines.push(format!(\n                \"field {} read_only_when: {}={}\",\n                field_name, condition.property, condition.value\n            ));\n        }\n\n        if !field_schema.constraints.is_empty() {\n            let constraints = field_schema\n                .constraints\n                .iter()\n                .map(render_constraint)\n                .collect::<Vec<_>>()\n                .join(\", \");\n            lines.push(format!(\"field {} constraints: {}\", field_name, constraints));\n        }\n    }\n\n    lines.join(\"\\n\")\n}\n\nfn render_field_type(field_type: &FieldType) -> String {\n    match field_type {\n        FieldType::String => \"string\".to_string(),\n        FieldType::Integer => \"integer\".to_string(),\n        FieldType::Float => \"float\".to_string(),\n        FieldType::Boolean => \"boolean\".to_string(),\n        FieldType::Array(inner) => format!(\"array<{}>\", render_field_type(inner)),\n        FieldType::Object(fields) => {\n            let mut names = fields.keys().cloned().collect::<Vec<_>>();\n            names.sort();\n            format!(\"object<{}>\", names.join(\"|\"))\n        }\n        FieldType::Enum(values) => format!(\"enum<{}>\", values.join(\"|\")),\n        FieldType::OneOf(branches) => format!(\n            \"one_of<{}>\",\n            branches\n                .iter()\n                .map(render_field_type)\n                .collect::<Vec<_>>()\n                .join(\"|\")\n        ),\n        FieldType::Any => \"any\".to_string(),\n    }\n}\n\nfn render_constraint(constraint: &op_state_store::Constraint) -> String {\n    match constraint {\n        op_state_store::Constraint::Min { value } => format!(\"min={value}\"),\n        op_state_store::Constraint::Max { value } => format!(\"max={value}\"),\n        op_state_store::Constraint::Pattern { regex } => format!(\"pattern={regex}\"),\n        op_state_store::Constraint::OneOf { values } => {\n            format!(\n                \"one_of={}\",\n                serde_json::to_string(values).unwrap_or_default()\n            )\n        }\n        op_state_store::Constraint::RequiresField { field } => format!(\"requires_field={field}\"),\n        op_state_store::Constraint::Custom { validator } => format!(\"custom={validator}\"),\n    }\n}\n\nfn extract_schema_title(schema_query_text: &str) -> &str {\n    schema_query_text\n        .lines()\n        .find_map(|line| line.strip_prefix(\"schema_name: \"))\n        .unwrap_or(\"unknown\")\n}\n\nfn extract_embedding(response_json: &Value) -> Result<Vec<f32>> {\n    let Some(embedding_values) = response_json\n        .get(\"data\")\n        .and_then(Value::as_array)\n        .and_then(|entries| entries.first())\n        .and_then(|entry| entry.get(\"embedding\"))\n        .and_then(Value::as_array)\n        .or_else(|| {\n            response_json\n                .get(\"embeddings\")\n                .and_then(Value::as_array)\n                .and_then(|entries| entries.first())\n                .and_then(Value::as_array)\n        })\n    else {\n        return Err(anyhow::anyhow!(\n            \"Voyage embeddings response did not contain a usable embedding\"\n        ));\n    };\n\n    let mut embedding = Vec::with_capacity(embedding_values.len());\n    for value in embedding_values {\n        let number = value\n            .as_f64()\n            .context(\"Voyage embedding contained a non-numeric value\")?;\n        embedding.push(number as f32);\n    }\n\n    ensure!(!embedding.is_empty(), \"Voyage embedding response was empty\");\n    Ok(embedding)\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use op_state_store::{Constraint, FieldSchema, ReadOnlyCondition};\n    use serde_json::json;\n    use std::collections::HashMap;\n\n    #[test]\n    fn should_preserve_identity_sled_abi_shape() {\n        // Canonical sled from op-identity: wireguard_pubkey(32) + mutation_index(8)\n        // + is_valid(1) + _pad(7) + hashed_footprint(32) + subid taxonomy + compliance fields.\n        assert!(\n            size_of::<IdentitySled>() >= 32 + 8 + 1 + 7 + 32,\n            \"IdentitySled ABI unexpectedly shrank (using canonical op-identity layout)\"\n        );\n    }\n\n    #[test]\n    fn should_format_trace_id_from_hashed_footprint() {\n        let trace_id = format_trace_id([0xAB; 32]);\n        assert_eq!(trace_id, format!(\"trace-{}\", \"ab\".repeat(32)));\n    }\n\n    #[test]\n    fn should_extract_embedding_from_openai_style_data_payload() {\n        let embedding = extract_embedding(&json!({\n            \"data\": [{\n                \"embedding\": [0.25, -0.5, 1.5]\n            }]\n        }))\n        .unwrap();\n\n        assert_eq!(embedding, vec![0.25, -0.5, 1.5]);\n    }\n\n    #[test]\n    fn should_extract_embedding_from_embeddings_array_payload() {\n        let embedding = extract_embedding(&json!({\n            \"embeddings\": [[0.1, 0.2, 0.3]]\n        }))\n        .unwrap();\n\n        assert_eq!(embedding, vec![0.1, 0.2, 0.3]);\n    }\n\n    #[test]\n    fn should_render_schema_embedding_text_deterministically() {\n        let mut nested_fields = HashMap::new();\n        nested_fields.insert(\n            \"beta\".to_string(),\n            FieldSchema {\n                field_type: FieldType::Boolean,\n                required: false,\n                description: String::new(),\n                default: None,\n                example: None,\n                constraints: vec![],\n                read_only: false,\n                read_only_when: None,\n            },\n        );\n        nested_fields.insert(\n            \"alpha\".to_string(),\n            FieldSchema {\n                field_type: FieldType::String,\n                required: false,\n                description: String::new(),\n                default: None,\n                example: None,\n                constraints: vec![],\n                read_only: false,\n                read_only_when: None,\n            },\n        );\n\n        let mut fields = HashMap::new();\n        fields.insert(\n            \"outcome_class\".to_string(),\n            FieldSchema {\n                field_type: FieldType::Enum(vec![\"deny\".into(), \"allow\".into()]),\n                required: true,\n                description: \"Outcome bucket\".into(),\n                default: None,\n                example: None,\n                constraints: vec![Constraint::OneOf {\n                    values: vec![simd_json::json!(\"allow\"), simd_json::json!(\"deny\")],\n                }],\n                read_only: false,\n                read_only_when: Some(ReadOnlyCondition {\n                    property: \"sealed\".into(),\n                    value: \"true\".into(),\n                }),\n            },\n        );\n        fields.insert(\n            \"tools_consulted\".to_string(),\n            FieldSchema {\n                field_type: FieldType::Array(Box::new(FieldType::Object(nested_fields))),\n                required: false,\n                description: \"Tools touched by the episode\".into(),\n                default: None,\n                example: None,\n                constraints: vec![Constraint::Min { value: 1.0 }],\n                read_only: true,\n                read_only_when: None,\n            },\n        );\n\n        let schema = PluginSchema {\n            name: \"ctl-plane-chatbot\".into(),\n            category: \"accountability\".into(),\n            version: \"1.0.0\".into(),\n            description: \"Human reviewable reasoning episodes\".into(),\n            display_name: None,\n            fields,\n            dependencies: vec![\"op-grpc-bridge\".into(), \"op-state-store\".into()],\n            example: None,\n            immutable_paths: vec![\"/episode_id\".into()],\n            tags: vec![\"audit\".into(), \"pii\".into()],\n            dialect: op_state_store::DEFAULT_SCHEMA_DIALECT.into(),\n            mutation_index: Some(7),\n            subids: std::collections::HashMap::new(),\n            methods: std::collections::HashMap::new(),\n            signals: vec![],\n            guarantees: op_state_store::PluginCapabilities::default(),\n        };\n\n        let rendered = render_schema_embedding_text(&schema);\n\n        assert!(rendered.contains(\"schema_name: ctl-plane-chatbot\"));\n        assert!(rendered.contains(\"schema_category: accountability\"));\n        assert!(rendered.contains(\"schema_tags: audit, pii\"));\n        assert!(rendered.contains(\"immutable_paths: /episode_id\"));\n        assert!(rendered.contains(\"dependencies: op-grpc-bridge, op-state-store\"));\n        assert!(rendered.contains(\n            \"field outcome_class: type=enum<deny|allow>, required=true, read_only=false, description=Outcome bucket\"\n        ));\n        assert!(rendered.contains(\"field outcome_class read_only_when: sealed=true\"));\n        assert!(rendered.contains(\"field tools_consulted: type=array<object<alpha|beta>>\"));\n    }\n}","lineStart":1,"lineEnd":793,"totalLines":793,"truncated":false}},"time":{"start":1783671005767,"end":1783671005836}}},"time":1783671005837}');
