b async fn get_bridge_info(&self, bridge_name: &str) -> Result<String> {\n        let result = self\n            .transact_one(serde_json::json!({\n                \"op\": \"select\",\n                \"table\": \"Bridge\",\n                \"where\": [[\"name\", \"==\", bridge_name]],\n                \"columns\": []\n            }))\n            .await?;\n        Ok(serde_json::to_string_pretty(&result)?)\n    }\n\n    // ── Mutation helpers ──────────────────────────────────────────────────\n\n    /// Create a bridge if it does not exist.\n    pub async fn create_bridge(&self, bridge_name: &str) -> Result<()> {\n        if self.bridge_exists(bridge_name).await? {\n            log::info!(\"Bridge {} already exists, skipping creation\", bridge_name);\n            return Ok(());\n        }\n        let ops = vec![\n            serde_json::json!({\n                \"op\": \"insert\",\n                \"table\": \"Bridge\",\n                \"row\": { \"name\": bridge_name, \"stp_enable\": false },\n                \"uuid-name\": \"new_bridge\"\n            }),\n            serde_json::json!({\n                \"op\": \"mutate\",\n                \"table\": \"Open_vSwitch\",","lineStart":250,"lineEnd":349,"totalLines":820,"truncated":true}},"title":"crates/op-network/src/rovs_proxy.rs","time":{"start":1783669104013,"end":1783669104031}}}');
