INSERT INTO part VALUES('prt_f4afddab7001cgUUrl6NV8mVN6','msg_f4afdc725001syf4l9rDM61bii','ses_0b516ef36ffeY2Uc26WsdLIdZW',1783669578423,1783669580744,'{"type":"reasoning","text":"The user is telling me that identity_sled.dat is deprecated and the actual container IS the sled now. This is a key architectural insight. Let me look at the identity_sled_dispatch to understand what it does currently, and then understand the new architecture where the container itself is the sled.\n\nLet me also understand what \"the container is the sled\" means in context - this likely means that instead of having a separate identity_sled binary/file, each container (e.g., the UUID-named Incus container) inherently IS a sled, with its identity derived from its WireGuard pubkey (which maps to its sessionid via Argon2).\n\nLet me read the identity_sled_dispatch to understand current state.","time":{"start":1783669578423,"end":1783669580742}}');
INSERT INTO part VALUES('prt_f4afde3c9001fZHc6JDajbttC8','msg_f4afdc725001syf4l9rDM61bii','ses_0b516ef36ffeY2Uc26WsdLIdZW',1783669580746,1783669580820,'{"type":"tool","tool":"read","callID":"call_902e81d53bb94db19afb2a73","state":{"status":"completed","input":{"filePath":"/home/jeremy/git/operation-dbus-proto/crates/op-grpc-bridge/src/identity_sled_dispatch.rs"},"output":"<path>/home/jeremy/git/operation-dbus-proto/crates/op-grpc-bridge/src/identity_sled_dispatch.rs</path>\n<type>file</type>\n<content>\n1: //! identity_sled method dispatch — the container is the sled is the identity.\n2: //!\n3: //! Executes the `identity_sled` plugin''s method surface against the\n4: //! MutationEngine''s authoritative state cache. Every call is already\n5: //! notarized in the immutable event chain by `dispatch_method_call` before it\n6: //! reaches here, so this module only performs the domain effect.\n7: //!\n8: //! Durability: sleds and the session-event \"snowball\" ledger persist to the\n9: //! Cozo relations `identity_sleds` / `session_events` (own sled-engine path —\n10: //! never the users-cozo or cognitive-mcp store, which other processes hold\n11: //! open). The event chain remains the durable proof; Cozo is the queryable\n12: //! archive plus the restart-warm source for the state cache. All Cozo I/O is\n13: //! synchronous sled disk work, so it runs under `spawn_blocking`.\n14: //!\n15: //! Provisioning: the sled inherits the Incus schema — `provision_container`\n16: //! creates the Incus instance (named by the derived session_id) and writes\n17: //! the sled in one mutation; a sled exists ⟺ its container exists.\n18: //!\n19: //! Compatibility: when the written identity is the host''s own (\"container\n20: //! zero\"), the legacy raw sled at `/dev/shm/plugin_schema.dat` is also\n21: //! refreshed via `op_identity::schema_bridge::write_sled_from_wg`, because\n22: //! AnnaScribe still gates arrivals on that file. That projection goes away\n23: //! when AnnaScribe reads the sealed blob directly.\n24: \n25: use std::path::PathBuf;\n26: use std::sync::OnceLock;\n27: \n28: use base64::Engine;\n29: use op_cozo_store::{CozoGraphShuttle, IdentitySledRecord};\n30: use op_plugins::state_plugins::identity_sled::{\n31:     ContainerIdentitySled, IdentitySledState, SessionEvent, SledBtrfsDevice,\n32: };\n33: use op_plugins::state_plugins::incus::{IncusInstance, IncusPlugin};\n34: use op_plugins::state_plugins::incus_device::Device;\n35: use serde_json::Value as JsonValue;\n36: use tokio::sync::OnceCell;\n37: \n38: use crate::mutation_engine::MutationEngine;\n39: \n40: /// Session events kept in present-state per session. The event chain is the\n41: /// durable ledger and Cozo `session_events` the queryable archive; the state\n42: /// cache only carries a recent window.\n43: const MAX_EVENTS_IN_STATE: usize = 256;\n44: \n45: /// Default Cozo path for the identity sled store. Own path — the sled engine\n46: /// is single-process, and `/var/lib/op-dbus/users-cozo` (op-web-server) and\n47: /// the cognitive-mcp store are already held by other processes.\n48: const DEFAULT_SLED_COZO_PATH: &str = \"/var/lib/op-dbus/identity-cozo\";\n49: \n50: /// In-state snowball ledger key inside the plugin state cache entry.\n51: #[derive(Debug, Clone, serde::Serialize, serde::Deserialize, Default)]\n52: struct SledCacheState {\n53:     #[serde(default)]\n54:     sleds: Vec<ContainerIdentitySled>,\n55:     #[serde(default)]\n56:     events: Vec<SessionEvent>,\n57: }\n58: \n59: /// Lazily opened durable store; `None` (with one warning) when the path can''t\n60: /// be opened — dispatch then runs cache-only, as before.\n61: fn sled_cozo() -> Option<&''static CozoGraphShuttle> {\n62:     static SLED_COZO: OnceLock<Option<CozoGraphShuttle>> = OnceLock::new();\n63:     SLED_COZO\n64:         .get_or_init(|| {\n65:             let path = std::env::var(\"IDENTITY_SLED_COZO_DB_PATH\")\n66:                 .unwrap_or_else(|_| DEFAULT_SLED_COZO_PATH.to_string());\n67:             match CozoGraphShuttle::new_persistent(PathBuf::from(&path)) {\n68:                 Ok(store) => Some(store),\n69:                 Err(e) => {\n70:                     tracing::warn!(\n71:                         %path,\n72:                         error = %e,\n73:                         \"identity sled Cozo store unavailable; running cache-only\"\n74:                     );\n75:                     None\n76:                 }\n77:             }\n78:         })\n79:         .as_ref()\n80: }\n81: \n82: fn sled_to_record(sled: &ContainerIdentitySled) -> IdentitySledRecord {\n83:     IdentitySledRecord {\n84:         session_id: sled.session_id.clone(),\n85:         wireguard_pubkey: sled.wireguard_pubkey.clone(),\n86:         interface: sled.interface.clone(),\n87:         peer_ip: sled.peer_ip.clone().unwrap_or_default(),\n88:         mutation_index: sled.mutation_index as i64,\n89:         hashed_footprint: sled.hashed_footprint.clone(),\n90:         trace_id: sled.trace_id.clone(),\n91:         schema_version: sled.schema_version as i64,\n92:         vector_id: sled.vector_id.clone(),\n93:         blob_ref: sled.blob_ref.clone().unwrap_or_default(),\n94:         btrfs_device_json: sled\n95:             .btrfs_device\n96:             .as_ref()\n97:             .and_then(|d| serde_json::to_string(d).ok())\n98:             .unwrap_or_default(),\n99:         instance_json: sled\n100:             .instance\n101:             .as_ref()\n102:             .and_then(|i| serde_json::to_string(i).ok())\n103:             .unwrap_or_default(),\n104:         session_started_at: sled.session_started_at,\n105:         last_seen_at: sled.last_seen_at,\n106:         active: sled.active,\n107:     }\n108: }\n109: \n110: fn record_to_sled(rec: &IdentitySledRecord) -> ContainerIdentitySled {\n111:     let parse_json = |label: &str, json: &str| -> Option<serde_json::Value> {\n112:         if json.is_empty() {\n113:             return None;\n114:         }\n115:         match serde_json::from_str(json) {\n116:             Ok(v) => Some(v),\n117:             Err(e) => {\n118:                 tracing::warn!(\n119:                     session_id = %rec.session_id,\n120:                     error = %e,\n121:                     \"dropping corrupt {label} on identity sled row\"\n122:                 );\n123:                 None\n124:             }\n125:         }\n126:     };\n127:     ContainerIdentitySled {\n128:         session_id: rec.session_id.clone(),\n129:         wireguard_pubkey: rec.wireguard_pubkey.clone(),\n130:         interface: rec.interface.clone(),\n131:         peer_ip: (!rec.peer_ip.is_empty()).then(|| rec.peer_ip.clone()),\n132:         mutation_index: rec.mutation_index.max(0) as u64,\n133:         hashed_footprint: rec.hashed_footprint.clone(),\n134:         trace_id: rec.trace_id.clone(),\n135:         schema_version: rec.schema_version.max(0) as u32,\n136:         vector_id: rec.vector_id.clone(),\n137:         blob_ref: (!rec.blob_ref.is_empty()).then(|| rec.blob_ref.clone()),\n138:         btrfs_device: parse_json(\"btrfs_device\", &rec.btrfs_device_json)\n139:             .and_then(|v| serde_json::from_value(v).ok()),\n140:         instance: parse_json(\"instance\", &rec.instance_json)\n141:             .and_then(|v| serde_json::from_value(v).ok()),\n142:         session_started_at: rec.session_started_at,\n143:         last_seen_at: rec.last_seen_at,\n144:         active: rec.active,\n145:     }\n146: }\n147: \n148: /// One-time cache warm from Cozo: after an opdbus restart the state cache is\n149: /// empty; the persisted sleds are its restart-warm source. One read at first\n150: /// dispatch — not a watcher, not a poll.\n151: async fn ensure_hydrated(engine: &MutationEngine) {\n152:     static HYDRATED: OnceCell<()> = OnceCell::const_new();\n153:     HYDRATED\n154:         .get_or_init(|| async {\n155:             let Some(cozo) = sled_cozo() else { return };\n156:             let cozo = cozo.clone();\n157:             let rows = tokio::task::spawn_blocking(move || cozo.list_identity_sleds()).await;\n158:             let rows = match rows {\n159:                 Ok(Ok(rows)) => rows,\n160:                 Ok(Err(e)) => {\n161:                     tracing::warn!(error = %e, \"identity sled hydration read failed\");\n162:                     return;\n163:                 }\n164:                 Err(e) => {\n165:                     tracing::warn!(error = %e, \"identity sled hydration task failed\");\n166:                     return;\n167:                 }\n168:             };\n169:             if rows.is_empty() {\n170:                 return;\n171:             }\n172:             let mut cache = read_cache(engine).await;\n173:             if !cache.sleds.is_empty() {\n174:                 return;\n175:             }\n176:             cache.sleds = rows.iter().map(record_to_sled).collect();\n177:             cache.sleds.sort_by(|a, b| a.session_id.cmp(&b.session_id));\n178:             if let Err(e) = write_cache(engine, &cache).await {\n179:                 tracing::warn!(error = %e, \"identity sled hydration cache write failed\");\n180:             }\n181:         })\n182:         .await;\n183: }\n184: \n185: /// Persist one sled row to Cozo; failure is logged, not fatal — the event\n186: /// chain already notarized the mutation.\n187: async fn persist_sled(sled: &ContainerIdentitySled) {\n188:     let Some(cozo) = sled_cozo() else { return };\n189:     let cozo = cozo.clone();\n190:     let rec = sled_to_record(sled);\n191:     match tokio::task::spawn_blocking(move || cozo.put_identity_sled(&rec)).await {\n192:         Ok(Ok(())) => {}\n193:         Ok(Err(e)) => tracing::warn!(error = %e, \"identity sled Cozo persist failed\"),\n194:         Err(e) => tracing::warn!(error = %e, \"identity sled Cozo persist task failed\"),\n195:     }\n196: }\n197: \n198: async fn read_cache(engine: &MutationEngine) -> SledCacheState {\n199:     let Some(state) = engine.get_state(\"identity_sled\").await else {\n200:         return SledCacheState::default();\n201:     };\n202:     simd_json::serde::from_owned_value(state).unwrap_or_default()\n203: }\n204: \n205: async fn write_cache(engine: &MutationEngine, cache: &SledCacheState) -> anyhow::Result<()> {\n206:     let owned = simd_json::serde::to_owned_value(cache)?;\n207:     engine\n208:         .update_state_cache(\"identity_sled\".to_string(), owned)\n209:         .await;\n210:     engine\n211:         .publish_plugin_projection_from_cache(\n212:             \"identity_sled\",\n213:             crate::mutation_engine::ChangeType::PropertySet,\n214:         )\n215:         .await?;\n216:     Ok(())\n217: }\n218: \n219: fn now() -> i64 {\n220:     chrono::Utc::now().timestamp()\n221: }\n222: \n223: fn arg_str(args: &JsonValue, key: &str) -> String {\n224:     args.get(key)\n225:         .and_then(|v| v.as_str())\n226:         .unwrap_or_default()\n227:         .to_string()\n228: }\n229: \n230: /// Derive the session id (= container name) from the supplied pubkey, using\n231: /// the provision-time PSK when present. Never trusts a supplied session_id.\n232: fn derive_session_id(args: &JsonValue, pubkey: &str) -> anyhow::Result<String> {\n233:     if let Some(psk_b64) = args\n234:         .get(\"psk\")\n235:         .and_then(|v| v.as_str())\n236:         .filter(|s| !s.is_empty())\n237:     {\n238:         let psk = base64::engine::general_purpose::STANDARD\n239:             .decode(psk_b64.trim())\n240:             .map_err(|e| anyhow::anyhow!(\"invalid psk base64: {e}\"))?;\n241:         op_identity::session::derive_session_id_from_psk(pubkey, &psk)\n242:     } else {\n243:         Ok(op_identity::session::derive_session_id(pubkey))\n244:     }\n245: }\n246: \n247: pub async fn dispatch_identity_sled_method(\n248:     engine: &MutationEngine,\n249:     method: &str,\n250:     args: &JsonValue,\n251: ) -> anyhow::Result<JsonValue> {\n252:     ensure_hydrated(engine).await;\n253: \n254:     match method {\n255:         \"get_identity\" => {\n256:             let session_id = arg_str(args, \"session_id\");\n257:             let cache = read_cache(engine).await;\n258:             let sled = if session_id.is_empty() {\n259:                 // Container zero: the host''s own identity.\n260:                 let host_pubkey = op_identity::wireguard::WireGuardIdentity::new()\n261:                     .get_local_pubkey()\n262:                     .unwrap_or_default();\n263:                 let host_id = op_identity::session::derive_session_id(&host_pubkey);\n264:                 cache\n265:                     .sleds\n266:                     .iter()\n267:                     .find(|s| s.session_id == host_id)\n268:                     .cloned()\n269:             } else {\n270:                 cache\n271:                     .sleds\n272:                     .iter()\n273:                     .find(|s| s.session_id == session_id)\n274:                     .cloned()\n275:             };\n276:             match sled {\n277:                 Some(identity) => Ok(serde_json::json!({ \"identity\": identity })),\n278:                 None => Err(anyhow::anyhow!(\n279:                     \"no identity sled for session ''{}''\",\n280:                     session_id\n281:                 )),\n282:             }\n283:         }\n284: \n285:         \"write_identity\" => {\n286:             let pubkey = arg_str(args, \"wireguard_pubkey\");\n287:             if pubkey.is_empty() {\n288:                 anyhow::bail!(\"write_identity requires wireguard_pubkey\");\n289:             }\n290:             // session_id is DERIVED from PSK + pubkey when PSK is supplied at provision time.\n291:             let session_id = derive_session_id(args, &pubkey)?;\n292:             let interface = arg_str(args, \"interface\");\n293:             let peer_ip = args\n294:                 .get(\"peer_ip\")\n295:                 .and_then(|v| v.as_str())\n296:                 .map(|s| s.to_string());\n297:             let blob_ref = args\n298:                 .get(\"blob_ref\")\n299:                 .and_then(|v| v.as_str())\n300:                 .map(|s| s.to_string());\n301:             let btrfs_device: Option<SledBtrfsDevice> = args\n302:                 .get(\"btrfs_device\")\n303:                 .cloned()\n304:                 .and_then(|v| serde_json::from_value(v).ok());\n305: \n306:             let mut cache = read_cache(engine).await;\n307:             let ts = now();\n308:             let existing = cache.sleds.iter_mut().find(|s| s.session_id == session_id);\n309:             let identity = match existing {\n310:                 Some(sled) => {\n311:                     sled.wireguard_pubkey = pubkey.clone();\n312:                     if !interface.is_empty() {\n313:                         sled.interface = interface;\n314:                     }\n315:                     if peer_ip.is_some() {\n316:                         sled.peer_ip = peer_ip;\n317:                     }\n318:                     if blob_ref.is_some() {\n319:                         sled.blob_ref = blob_ref;\n320:                     }\n321:                     if btrfs_device.is_some() {\n322:                         sled.btrfs_device = btrfs_device;\n323:                     }\n324:                     sled.mutation_index += 1;\n325:                     sled.last_seen_at = ts;\n326:                     sled.active = true;\n327:                     sled.clone()\n328:                 }\n329:                 None => {\n330:                     let sled = ContainerIdentitySled {\n331:                         session_id: session_id.clone(),\n332:                         wireguard_pubkey: pubkey.clone(),\n333:                         interface,\n334:                         peer_ip,\n335:                         mutation_index: 0,\n336:                         hashed_footprint: String::new(),\n337:                         trace_id: String::new(),\n338:                         schema_version: 0,\n339:                         vector_id: String::new(),\n340:                         blob_ref,\n341:                         btrfs_device,\n342:                         instance: None,\n343:                         session_started_at: ts,\n344:                         last_seen_at: ts,\n345:                         active: true,\n346:                     };\n347:                     cache.sleds.push(sled.clone());\n348:                     cache.sleds.sort_by(|a, b| a.session_id.cmp(&b.session_id));\n349:                     sled\n350:                 }\n351:             };\n352:             write_cache(engine, &cache).await?;\n353:             persist_sled(&identity).await;\n354: \n355:             // Container zero: refresh the legacy raw sled AnnaScribe gates on.\n356:             let host_pubkey = op_identity::wireguard::WireGuardIdentity::new()\n357:                 .get_local_pubkey()\n358:                 .unwrap_or_default();\n359:             if !host_pubkey.is_empty() && host_pubkey == pubkey {\n360:                 if let Err(e) = op_identity::schema_bridge::write_sled_from_wg(&pubkey) {\n361:                     tracing::warn!(error = %e, \"legacy sled projection write failed\");\n362:                 }\n363:             }\n364: \n365:             Ok(serde_json::json!({ \"identity\": identity }))\n366:         }\n367: \n368:         \"provision_container\" => {\n369:             let pubkey = arg_str(args, \"wireguard_pubkey\");\n370:             if pubkey.is_empty() {\n371:                 anyhow::bail!(\"provision_container requires wireguard_pubkey\");\n372:             }\n373:             let session_id = derive_session_id(args, &pubkey)?;\n374: \n375:             let mut instance: IncusInstance = match args.get(\"instance\") {\n376:                 Some(v) => {\n377:                     // `name`/`status`/`type` are mandatory on IncusInstance\n378:                     // (it also models read-back instances, where they always\n379:                     // exist) but irrelevant to a provision-time override:\n380:                     // `name` is always forced to the derived session_id below\n381:                     // and `status`/`type` default to their obvious values —\n382:                     // inject placeholders so a partial override (e.g.\n383:                     // image-only) still parses.\n384:                     let mut v = v.clone();\n385:                     if let Some(obj) = v.as_object_mut() {\n386:                         obj.entry(\"name\").or_insert_with(|| serde_json::json!(\"\"));\n387:                         obj.entry(\"status\").or_insert_with(|| serde_json::json!(\"\"));\n388:                         obj.entry(\"type\").or_insert_with(|| serde_json::json!(\"\"));\n389:                     }\n390:                     serde_json::from_value(v)\n391:                         .map_err(|e| anyhow::anyhow!(\"invalid instance definition: {e}\"))?\n392:                 }\n393:                 None => IncusInstance::default(),\n394:             };\n395:             // The container name IS the identity — always the derived id.\n396:             instance.name = session_id.clone();\n397:             if instance.instance_type.is_empty() {\n398:                 instance.instance_type = \"container\".to_string();\n399:             }\n400:             if instance.status.is_empty() {\n401:                 instance.status = \"Running\".to_string();\n402:             }\n403:             // No profile override = the Incus \"default\" profile, which on\n404:             // this host supplies only the root disk device (no nic) — an\n405:             // empty profile list would make apply_create pass --no-profiles,\n406:             // and Incus then fails instance creation outright with no root\n407:             // device to mount.\n408:             if instance.profiles.is_empty() {\n409:                 instance.profiles = vec![\"default\".to_string()];\n410:             }\n411:             // Hard rule: no container NIC or IP; all I/O over the UDS surface.\n412:             if instance\n413:                 .devices\n414:                 .iter()\n415:                 .chain(instance.expanded_devices.iter())\n416:                 .any(|d| matches!(d.device, Device::Nic(_)))\n417:             {\n418:                 anyhow::bail!(\n419:                     \"nic devices are not allowed: containers get no NIC or IP \\\n420:                      (all container I/O goes over the UDS socket surface)\"\n421:                 );\n422:             }\n423: \n424:             let blob_ref = args\n425:                 .get(\"blob_ref\")\n426:                 .and_then(|v| v.as_str())\n427:                 .map(|s| s.to_string());\n428:             let btrfs_device: Option<SledBtrfsDevice> = args\n429:                 .get(\"btrfs_device\")\n430:                 .cloned()\n431:                 .and_then(|v| serde_json::from_value(v).ok());\n432: \n433:             let cache = read_cache(engine).await;\n434:             if cache\n435:                 .sleds\n436:                 .iter()\n437:                 .any(|s| s.session_id == session_id && s.active)\n438:             {\n439:                 anyhow::bail!(\n440:                     \"identity sled ''{}'' is already provisioned and active\",\n441:                     session_id\n442:                 );\n443:             }\n444:             drop(cache);\n445: \n446:             // Create the container first: a sled exists ⟺ its container\n447:             // exists, so an incus failure means no sled row.\n448:             IncusPlugin::apply_create(&instance)\n449:                 .await\n450:                 .map_err(|e| anyhow::anyhow!(\"incus create for ''{session_id}'' failed: {e:#}\"))?;\n451: \n452:             let ts = now();\n453:             let sled = ContainerIdentitySled {\n454:                 session_id: session_id.clone(),\n455:                 wireguard_pubkey: pubkey,\n456:                 interface: String::new(),\n457:                 peer_ip: None,\n458:                 mutation_index: 0,\n459:                 hashed_footprint: String::new(),\n460:                 trace_id: String::new(),\n461:                 schema_version: 0,\n462:                 vector_id: String::new(),\n463:                 blob_ref,\n464:                 btrfs_device,\n465:                 instance: Some(instance),\n466:                 session_started_at: ts,\n467:                 last_seen_at: ts,\n468:                 active: true,\n469:             };\n470:             let mut cache = read_cache(engine).await;\n471:             cache.sleds.retain(|s| s.session_id != session_id);\n472:             cache.sleds.push(sled.clone());\n473:             cache.sleds.sort_by(|a, b| a.session_id.cmp(&b.session_id));\n474:             write_cache(engine, &cache).await?;\n475:             persist_sled(&sled).await;\n476: \n477:             Ok(serde_json::json!({ \"identity\": sled }))\n478:         }\n479: \n480:         \"attach_btrfs_device\" => {\n481:             let session_id = arg_str(args, \"session_id\");\n482:             if session_id.is_empty() {\n483:                 anyhow::bail!(\"attach_btrfs_device requires session_id\");\n484:             }\n485:             let mut cache = read_cache(engine).await;\n486:             let Some(sled) = cache.sleds.iter_mut().find(|s| s.session_id == session_id) else {\n487:                 anyhow::bail!(\"no identity sled for session ''{}''\", session_id);\n488:             };\n489:             let Some(device) = sled.btrfs_device.clone() else {\n490:                 anyhow::bail!(\n491:                     \"identity sled ''{}'' has no registered btrfs device\",\n492:                     session_id\n493:                 );\n494:             };\n495:             if device.attached {\n496:                 anyhow::bail!(\"btrfs device ''{}'' is already attached\", device.device_path);\n497:             }\n498:             if device.device_path.is_empty() || device.mount_point.is_empty() {\n499:                 anyhow::bail!(\"btrfs device needs both device_path and mount_point\");\n500:             }\n501: \n502:             let dev = PathBuf::from(&device.device_path);\n503:             let mount = PathBuf::from(&device.mount_point);\n504:             tokio::task::spawn_blocking(move || op_network::btrfs::device_add(&dev, &mount))\n505:                 .await\n506:                 .map_err(|e| anyhow::anyhow!(\"btrfs device add task failed: {e}\"))??;\n507: \n508:             if let Some(d) = sled.btrfs_device.as_mut() {\n509:                 d.attached = true;\n510:             }\n511:             sled.mutation_index += 1;\n512:             sled.last_seen_at = now();\n513:             let identity = sled.clone();\n514:             write_cache(engine, &cache).await?;\n515:             persist_sled(&identity).await;\n516:             Ok(serde_json::json!({ \"identity\": identity }))\n517:         }\n518: \n519:         \"touch_session\" => {\n520:             let session_id = arg_str(args, \"session_id\");\n521:             let mut cache = read_cache(engine).await;\n522:             let Some(sled) = cache.sleds.iter_mut().find(|s| s.session_id == session_id) else {\n523:                 anyhow::bail!(\"no identity sled for session ''{}''\", session_id);\n524:             };\n525:             let ts = now();\n526:             sled.last_seen_at = ts;\n527:             sled.active = true;\n528:             write_cache(engine, &cache).await?;\n529:             if let Some(cozo) = sled_cozo() {\n530:                 let cozo = cozo.clone();\n531:                 let sid = session_id.clone();\n532:                 match tokio::task::spawn_blocking(move || cozo.touch_identity_sled(&sid, ts, true))\n533:                     .await\n534:                 {\n535:                     Ok(Ok(())) => {}\n536:                     Ok(Err(e)) => tracing::warn!(error = %e, \"identity sled touch persist failed\"),\n537:                     Err(e) => tracing::warn!(error = %e, \"identity sled touch task failed\"),\n538:                 }\n539:             }\n540:             Ok(serde_json::json!({ \"success\": true }))\n541:         }\n542: \n543:         \"record_session_event\" => {\n544:             let session_id = arg_str(args, \"session_id\");\n545:             let kind = arg_str(args, \"kind\");\n546:             if session_id.is_empty() || kind.is_empty() {\n547:                 anyhow::bail!(\"record_session_event requires session_id and kind\");\n548:             }\n549:             let subid = arg_str(args, \"subid\");\n550:             let content = arg_str(args, \"content\");\n551:             let created_at = now();\n552: \n553:             // Durable append first: Cozo allocates the seq (monotonic across\n554:             // restarts, unlike the capped in-state window).\n555:             let mut cozo_seq: Option<u64> = None;\n556:             if let Some(cozo) = sled_cozo() {\n557:                 let cozo = cozo.clone();\n558:                 let (sid, k, sb, c) = (\n559:                     session_id.clone(),\n560:                     kind.clone(),\n561:                     subid.clone(),\n562:                     content.clone(),\n563:                 );\n564:                 match tokio::task::spawn_blocking(move || {\n565:                     cozo.append_session_event(&sid, &k, &sb, &c, created_at)\n566:                 })\n567:                 .await\n568:                 {\n569:                     Ok(Ok(seq)) => cozo_seq = Some(seq.max(0) as u64),\n570:                     Ok(Err(e)) => tracing::warn!(error = %e, \"session event persist failed\"),\n571:                     Err(e) => tracing::warn!(error = %e, \"session event persist task failed\"),\n572:                 }\n573:             }\n574: \n575:             let mut cache = read_cache(engine).await;\n576:             let seq = cozo_seq.unwrap_or_else(|| {\n577:                 cache\n578:                     .events\n579:                     .iter()\n580:                     .filter(|e| e.session_id == session_id)\n581:                     .map(|e| e.seq)\n582:                     .max()\n583:                     .map(|s| s + 1)\n584:                     .unwrap_or(0)\n585:             });\n586:             cache.events.push(SessionEvent {\n587:                 session_id,\n588:                 seq,\n589:                 kind,\n590:                 subid,\n591:                 content,\n592:                 created_at,\n593:             });\n594:             if cache.events.len() > MAX_EVENTS_IN_STATE {\n595:                 let excess = cache.events.len() - MAX_EVENTS_IN_STATE;\n596:                 cache.events.drain(..excess);\n597:             }\n598:             write_cache(engine, &cache).await?;\n599:             Ok(serde_json::json!({ \"success\": true }))\n600:         }\n601: \n602:         \"get_session_history\" => {\n603:             let session_id = arg_str(args, \"session_id\");\n604:             let limit = args.get(\"limit\").and_then(|v| v.as_u64()).unwrap_or(0) as usize;\n605: \n606:             // Prefer the durable archive; fall back to the in-state window.\n607:             if let Some(cozo) = sled_cozo() {\n608:                 let cozo = cozo.clone();\n609:                 let sid = session_id.clone();\n610:                 match tokio::task::spawn_blocking(move || cozo.list_session_events(&sid, limit))\n611:                     .await\n612:                 {\n613:                     Ok(Ok(rows)) => {\n614:                         let events: Vec<SessionEvent> = rows\n615:                             .iter()\n616:                             .map(|r| SessionEvent {\n617:                                 session_id: r.session_id.clone(),\n618:                                 seq: r.seq.max(0) as u64,\n619:                                 kind: r.kind.clone(),\n620:                                 subid: r.subid.clone(),\n621:                                 content: r.content.clone(),\n622:                                 created_at: r.created_at,\n623:                             })\n624:                             .collect();\n625:                         return Ok(serde_json::json!({ \"events\": events }));\n626:                     }\n627:                     Ok(Err(e)) => {\n628:                         tracing::warn!(error = %e, \"session history read failed; using cache\")\n629:                     }\n630:                     Err(e) => {\n631:                         tracing::warn!(error = %e, \"session history task failed; using cache\")\n632:                     }\n633:                 }\n634:             }\n635: \n636:             let cache = read_cache(engine).await;\n637:             let mut events: Vec<&SessionEvent> = cache\n638:                 .events\n639:                 .iter()\n640:                 .filter(|e| e.session_id == session_id)\n641:                 .collect();\n642:             events.sort_by(|a, b| b.seq.cmp(&a.seq));\n643:             if limit > 0 {\n644:                 events.truncate(limit);\n645:             }\n646:             Ok(serde_json::json!({ \"events\": events }))\n647:         }\n648: \n649:         other => Err(anyhow::anyhow!(\"unknown identity_sled method ''{}''\", other)),\n650:     }\n651: }\n652: \n653: /// Expose the typed state for consumers that want the full sled set.\n654: pub async fn current_state(engine: &MutationEngine) -> IdentitySledState {\n655:     let cache = read_cache(engine).await;\n656:     IdentitySledState { sleds: cache.sleds }\n657: }\n\n(End of file - total 657 lines)\n</content>","metadata":{"preview":"//! identity_sled method dispatch — the container is the sled is the identity.\n//!\n//! Executes the `identity_sled` plugin''s method surface against the\n//! MutationEngine''s authoritative state cache. Every call is already\n//! notarized in the immutable event chain by `dispatch_method_call` before it\n//! reaches here, so this module only performs the domain effect.\n//!\n//! Durability: sleds and the session-event \"snowball\" ledger persist to the\n//! Cozo relations `identity_sleds` / `session_events` (own sled-engine path —\n//! never the users-cozo or cognitive-mcp store, which other processes hold\n//! open). The event chain remains the durable proof; Cozo is the queryable\n//! archive plus the restart-warm source for the state cache. All Cozo I/O is\n//! synchronous sled disk work, so it runs under `spawn_blocking`.\n//!\n//! Provisioning: the sled inherits the Incus schema — `provision_container`\n//! creates the Incus instance (named by the derived session_id) and writes\n//! the sled in one mutation; a sled exists ⟺ its container exists.\n//!\n//! Compatibility: when the written identity is the host''s own (\"container\n//! zero\"), the legacy raw sled at `/dev/shm/plugin_schema.dat` is also","truncated":false,"loaded":[],"display":{"type":"file","path":"/home/jeremy/git/operation-dbus-proto/crates/op-grpc-bridge/src/identity_sled_dispatch.rs","text":"//! identity_sled method dispatch — the container is the sled is the identity.\n//!\n//! Executes the `identity_sled` plugin''s method surface against the\n//! MutationEngine''s authoritative state cache. Every call is already\n//! notarized in the immutable event chain by `dispatch_method_call` before it\n//! reaches here, so this module only performs the domain effect.\n//!\n//! Durability: sleds and the session-event \"snowball\" ledger persist to the\n//! Cozo relations `identity_sleds` / `session_events` (own sled-engine path —\n//! never the users-cozo or cognitive-mcp store, which other processes hold\n//! open). The event chain remains the durable proof; Cozo is the queryable\n//! archive plus the restart-warm source for the state cache. All Cozo I/O is\n//! synchronous sled disk work, so it runs under `spawn_blocking`.\n//!\n//! Provisioning: the sled inherits the Incus schema — `provision_container`\n//! creates the Incus instance (named by the derived session_id) and writes\n//! the sled in one mutation; a sled exists ⟺ its container exists.\n//!\n//! Compatibility: when the written identity is the host''s own (\"container\n//! zero\"), the legacy raw sled at `/dev/shm/plugin_schema.dat` is also\n//! refreshed via `op_identity::schema_bridge::write_sled_from_wg`, because\n//! AnnaScribe still gates arrivals on that file. That projection goes away\n//! when AnnaScribe reads the sealed blob directly.\n\nuse std::path::PathBuf;\nuse std::sync::OnceLock;\n\nuse base64::Engine;\nuse op_cozo_store::{CozoGraphShuttle, IdentitySledRecord};\nuse op_plugins::state_plugins::identity_sled::{\n    ContainerIdentitySled, IdentitySledState, SessionEvent, SledBtrfsDevice,\n};\nuse op_plugins::state_plugins::incus::{IncusInstance, IncusPlugin};\nuse op_plugins::state_plugins::incus_device::Device;\nuse serde_json::Value as JsonValue;\nuse tokio::sync::OnceCell;\n\nuse crate::mutation_engine::MutationEngine;\n\n/// Session events kept in present-state per session. The event chain is the\n/// durable ledger and Cozo `session_events` the queryable archive; the state\n/// cache only carries a recent window.\nconst MAX_EVENTS_IN_STATE: usize = 256;\n\n/// Default Cozo path for the identity sled store. Own path — the sled engine\n/// is single-process, and `/var/lib/op-dbus/users-cozo` (op-web-server) and\n/// the cognitive-mcp store are already held by other processes.\nconst DEFAULT_SLED_COZO_PATH: &str = \"/var/lib/op-dbus/identity-cozo\";\n\n/// In-state snowball ledger key inside the plugin state cache entry.\n#[derive(Debug, Clone, serde::Serialize, serde::Deserialize, Default)]\nstruct SledCacheState {\n    #[serde(default)]\n    sleds: Vec<ContainerIdentitySled>,\n    #[serde(default)]\n    events: Vec<SessionEvent>,\n}\n\n/// Lazily opened durable store; `None` (with one warning) when the path can''t\n/// be opened — dispatch then runs cache-only, as before.\nfn sled_cozo() -> Option<&''static CozoGraphShuttle> {\n    static SLED_COZO: OnceLock<Option<CozoGraphShuttle>> = OnceLock::new();\n    SLED_COZO\n        .get_or_init(|| {\n            let path = std::env::var(\"IDENTITY_SLED_COZO_DB_PATH\")\n                .unwrap_or_else(|_| DEFAULT_SLED_COZO_PATH.to_string());\n            match CozoGraphShuttle::new_persistent(PathBuf::from(&path)) {\n                Ok(store) => Some(store),\n                Err(e) => {\n                    tracing::warn!(\n                        %path,\n                        error = %e,\n                        \"identity sled Cozo store unavailable; running cache-only\"\n                    );\n                    None\n                }\n            }\n        })\n        .as_ref()\n}\n\nfn sled_to_record(sled: &ContainerIdentitySled) -> IdentitySledRecord {\n    IdentitySledRecord {\n        session_id: sled.session_id.clone(),\n        wireguard_pubkey: sled.wireguard_pubkey.clone(),\n        interface: sled.interface.clone(),\n        peer_ip: sled.peer_ip.clone().unwrap_or_default(),\n        mutation_index: sled.mutation_index as i64,\n        hashed_footprint: sled.hashed_footprint.clone(),\n        trace_id: sled.trace_id.clone(),\n        schema_version: sled.schema_version as i64,\n        vector_id: sled.vector_id.clone(),\n        blob_ref: sled.blob_ref.clone().unwrap_or_default(),\n        btrfs_device_json: sled\n            .btrfs_device\n            .as_ref()\n            .and_then(|d| serde_json::to_string(d).ok())\n            .unwrap_or_default(),\n        instance_json: sled\n            .instance\n            .as_ref()\n            .and_then(|i| serde_json::to_string(i).ok())\n            .unwrap_or_default(),\n        session_started_at: sled.session_started_at,\n        last_seen_at: sled.last_seen_at,\n        active: sled.active,\n    }\n}\n\nfn record_to_sled(rec: &IdentitySledRecord) -> ContainerIdentitySled {\n    let parse_json = |label: &str, json: &str| -> Option<serde_json::Value> {\n        if json.is_empty() {\n            return None;\n        }\n        match serde_json::from_str(json) {\n            Ok(v) => Some(v),\n            Err(e) => {\n                tracing::warn!(\n                    session_id = %rec.session_id,\n                    error = %e,\n                    \"dropping corrupt {label} on identity sled row\"\n                );\n                None\n            }\n        }\n    };\n    ContainerIdentitySled {\n        session_id: rec.session_id.clone(),\n        wireguard_pubkey: rec.wireguard_pubkey.clone(),\n        interface: rec.interface.clone(),\n        peer_ip: (!rec.peer_ip.is_empty()).then(|| rec.peer_ip.clone()),\n        mutation_index: rec.mutation_index.max(0) as u64,\n        hashed_footprint: rec.hashed_footprint.clone(),\n        trace_id: rec.trace_id.clone(),\n        schema_version: rec.schema_version.max(0) as u32,\n        vector_id: rec.vector_id.clone(),\n        blob_ref: (!rec.blob_ref.is_empty()).then(|| rec.blob_ref.clone()),\n        btrfs_device: parse_json(\"btrfs_device\", &rec.btrfs_device_json)\n            .and_then(|v| serde_json::from_value(v).ok()),\n        instance: parse_json(\"instance\", &rec.instance_json)\n            .and_then(|v| serde_json::from_value(v).ok()),\n        session_started_at: rec.session_started_at,\n        last_seen_at: rec.last_seen_at,\n        active: rec.active,\n    }\n}\n\n/// One-time cache warm from Cozo: after an opdbus restart the state cache is\n/// empty; the persisted sleds are its restart-warm source. One read at first\n/// dispatch — not a watcher, not a poll.\nasync fn ensure_hydrated(engine: &MutationEngine) {\n    static HYDRATED: OnceCell<()> = OnceCell::const_new();\n    HYDRATED\n        .get_or_init(|| async {\n            let Some(cozo) = sled_cozo() else { return };\n            let cozo = cozo.clone();\n            let rows = tokio::task::spawn_blocking(move || cozo.list_identity_sleds()).await;\n            let rows = match rows {\n                Ok(Ok(rows)) => rows,\n                Ok(Err(e)) => {\n                    tracing::warn!(error = %e, \"identity sled hydration read failed\");\n                    return;\n                }\n                Err(e) => {\n                    tracing::warn!(error = %e, \"identity sled hydration task failed\");\n                    return;\n                }\n            };\n            if rows.is_empty() {\n                return;\n            }\n            let mut cache = read_cache(engine).await;\n            if !cache.sleds.is_empty() {\n                return;\n            }\n            cache.sleds = rows.iter().map(record_to_sled).collect();\n            cache.sleds.sort_by(|a, b| a.session_id.cmp(&b.session_id));\n            if let Err(e) = write_cache(engine, &cache).await {\n                tracing::warn!(error = %e, \"identity sled hydration cache write failed\");\n            }\n        })\n        .await;\n}\n\n/// Persist one sled row to Cozo; failure is logged, not fatal — the event\n/// chain already notarized the mutation.\nasync fn persist_sled(sled: &ContainerIdentitySled) {\n    let Some(cozo) = sled_cozo() else { return };\n    let cozo = cozo.clone();\n    let rec = sled_to_record(sled);\n    match tokio::task::spawn_blocking(move || cozo.put_identity_sled(&rec)).await {\n        Ok(Ok(())) => {}\n        Ok(Err(e)) => tracing::warn!(error = %e, \"identity sled Cozo persist failed\"),\n        Err(e) => tracing::warn!(error = %e, \"identity sled Cozo persist task failed\"),\n    }\n}\n\nasync fn read_cache(engine: &MutationEngine) -> SledCacheState {\n    let Some(state) = engine.get_state(\"identity_sled\").await else {\n        return SledCacheState::default();\n    };\n    simd_json::serde::from_owned_value(state).unwrap_or_default()\n}\n\nasync fn write_cache(engine: &MutationEngine, cache: &SledCacheState) -> anyhow::Result<()> {\n    let owned = simd_json::serde::to_owned_value(cache)?;\n    engine\n        .update_state_cache(\"identity_sled\".to_string(), owned)\n        .await;\n    engine\n        .publish_plugin_projection_from_cache(\n            \"identity_sled\",\n            crate::mutation_engine::ChangeType::PropertySet,\n        )\n        .await?;\n    Ok(())\n}\n\nfn now() -> i64 {\n    chrono::Utc::now().timestamp()\n}\n\nfn arg_str(args: &JsonValue, key: &str) -> String {\n    args.get(key)\n        .and_then(|v| v.as_str())\n        .unwrap_or_default()\n        .to_string()\n}\n\n/// Derive the session id (= container name) from the supplied pubkey, using\n/// the provision-time PSK when present. Never trusts a supplied session_id.\nfn derive_session_id(args: &JsonValue, pubkey: &str) -> anyhow::Result<String> {\n    if let Some(psk_b64) = args\n        .get(\"psk\")\n        .and_then(|v| v.as_str())\n        .filter(|s| !s.is_empty())\n    {\n        let psk = base64::engine::general_purpose::STANDARD\n            .decode(psk_b64.trim())\n            .map_err(|e| anyhow::anyhow!(\"invalid psk base64: {e}\"))?;\n        op_identity::session::derive_session_id_from_psk(pubkey, &psk)\n    } else {\n        Ok(op_identity::session::derive_session_id(pubkey))\n    }\n}\n\npub async fn dispatch_identity_sled_method(\n    engine: &MutationEngine,\n    method: &str,\n    args: &JsonValue,\n) -> anyhow::Result<JsonValue> {\n    ensure_hydrated(engine).await;\n\n    match method {\n        \"get_identity\" => {\n            let session_id = arg_str(args, \"session_id\");\n            let cache = read_cache(engine).await;\n            let sled = if session_id.is_empty() {\n                // Container zero: the host''s own identity.\n                let host_pubkey = op_identity::wireguard::WireGuardIdentity::new()\n                    .get_local_pubkey()\n                    .unwrap_or_default();\n                let host_id = op_identity::session::derive_session_id(&host_pubkey);\n                cache\n                    .sleds\n                    .iter()\n                    .find(|s| s.session_id == host_id)\n                    .cloned()\n            } else {\n                cache\n                    .sleds\n                    .iter()\n                    .find(|s| s.session_id == session_id)\n                    .cloned()\n            };\n            match sled {\n                Some(identity) => Ok(serde_json::json!({ \"identity\": identity })),\n                None => Err(anyhow::anyhow!(\n                    \"no identity sled for session ''{}''\",\n                    session_id\n                )),\n            }\n        }\n\n        \"write_identity\" => {\n            let pubkey = arg_str(args, \"wireguard_pubkey\");\n            if pubkey.is_empty() {\n                anyhow::bail!(\"write_identity requires wireguard_pubkey\");\n            }\n            // session_id is DERIVED from PSK + pubkey when PSK is supplied at provision time.\n            let session_id = derive_session_id(args, &pubkey)?;\n            let interface = arg_str(args, \"interface\");\n            let peer_ip = args\n                .get(\"peer_ip\")\n                .and_then(|v| v.as_str())\n                .map(|s| s.to_string());\n            let blob_ref = args\n                .get(\"blob_ref\")\n                .and_then(|v| v.as_str())\n                .map(|s| s.to_string());\n            let btrfs_device: Option<SledBtrfsDevice> = args\n                .get(\"btrfs_device\")\n                .cloned()\n                .and_then(|v| serde_json::from_value(v).ok());\n\n            let mut cache = read_cache(engine).await;\n            let ts = now();\n            let existing = cache.sleds.iter_mut().find(|s| s.session_id == session_id);\n            let identity = match existing {\n                Some(sled) => {\n                    sled.wireguard_pubkey = pubkey.clone();\n                    if !interface.is_empty() {\n                        sled.interface = interface;\n                    }\n                    if peer_ip.is_some() {\n                        sled.peer_ip = peer_ip;\n                    }\n                    if blob_ref.is_some() {\n                        sled.blob_ref = blob_ref;\n                    }\n                    if btrfs_device.is_some() {\n                        sled.btrfs_device = btrfs_device;\n                    }\n                    sled.mutation_index += 1;\n                    sled.last_seen_at = ts;\n                    sled.active = true;\n                    sled.clone()\n                }\n                None => {\n                    let sled = ContainerIdentitySled {\n                        session_id: session_id.clone(),\n                        wireguard_pubkey: pubkey.clone(),\n                        interface,\n                        peer_ip,\n                        mutation_index: 0,\n                        hashed_footprint: String::new(),\n                        trace_id: String::new(),\n                        schema_version: 0,\n                        vector_id: String::new(),\n                        blob_ref,\n                        btrfs_device,\n                        instance: None,\n                        session_started_at: ts,\n                        last_seen_at: ts,\n                        active: true,\n                    };\n                    cache.sleds.push(sled.clone());\n                    cache.sleds.sort_by(|a, b| a.session_id.cmp(&b.session_id));\n                    sled\n                }\n            };\n            write_cache(engine, &cache).await?;\n            persist_sled(&identity).await;\n\n            // Container zero: refresh the legacy raw sled AnnaScribe gates on.\n            let host_pubkey = op_identity::wireguard::WireGuardIdentity::new()\n                .get_local_pubkey()\n                .unwrap_or_default();\n            if !host_pubkey.is_empty() && host_pubkey == pubkey {\n                if let Err(e) = op_identity::schema_bridge::write_sled_from_wg(&pubkey) {\n                    tracing::warn!(error = %e, \"legacy sled projection write failed\");\n                }\n            }\n\n            Ok(serde_json::json!({ \"identity\": identity }))\n        }\n\n        \"provision_container\" => {\n            let pubkey = arg_str(args, \"wireguard_pubkey\");\n            if pubkey.is_empty() {\n                anyhow::bail!(\"provision_container requires wireguard_pubkey\");\n            }\n            let session_id = derive_session_id(args, &pubkey)?;\n\n            let mut instance: IncusInstance = match args.get(\"instance\") {\n                Some(v) => {\n                    // `name`/`status`/`type` are mandatory on IncusInstance\n                    // (it also models read-back instances, where they always\n                    // exist) but irrelevant to a provision-time override:\n                    // `name` is always forced to the derived session_id below\n                    // and `status`/`type` default to their obvious values —\n                    // inject placeholders so a partial override (e.g.\n                    // image-only) still parses.\n                    let mut v = v.clone();\n                    if let Some(obj) = v.as_object_mut() {\n                        obj.entry(\"name\").or_insert_with(|| serde_json::json!(\"\"));\n                        obj.entry(\"status\").or_insert_with(|| serde_json::json!(\"\"));\n                        obj.entry(\"type\").or_insert_with(|| serde_json::json!(\"\"));\n                    }\n                    serde_json::from_value(v)\n                        .map_err(|e| anyhow::anyhow!(\"invalid instance definition: {e}\"))?\n                }\n                None => IncusInstance::default(),\n            };\n            // The container name IS the identity — always the derived id.\n            instance.name = session_id.clone();\n            if instance.instance_type.is_empty() {\n                instance.instance_type = \"container\".to_string();\n            }\n            if instance.status.is_empty() {\n                instance.status = \"Running\".to_string();\n            }\n            // No profile override = the Incus \"default\" profile, which on\n            // this host supplies only the root disk device (no nic) — an\n            // empty profile list would make apply_create pass --no-profiles,\n            // and Incus then fails instance creation outright with no root\n            // device to mount.\n            if instance.profiles.is_empty() {\n                instance.profiles = vec![\"default\".to_string()];\n            }\n            // Hard rule: no container NIC or IP; all I/O over the UDS surface.\n            if instance\n                .devices\n                .iter()\n                .chain(instance.expanded_devices.iter())\n                .any(|d| matches!(d.device, Device::Nic(_)))\n            {\n                anyhow::bail!(\n                    \"nic devices are not allowed: containers get no NIC or IP \\\n                     (all container I/O goes over the UDS socket surface)\"\n                );\n            }\n\n            let blob_ref = args\n                .get(\"blob_ref\")\n                .and_then(|v| v.as_str())\n                .map(|s| s.to_string());\n            let btrfs_device: Option<SledBtrfsDevice> = args\n                .get(\"btrfs_device\")\n                .cloned()\n                .and_then(|v| serde_json::from_value(v).ok());\n\n            let cache = read_cache(engine).await;\n            if cache\n                .sleds\n                .iter()\n                .any(|s| s.session_id == session_id && s.active)\n            {\n                anyhow::bail!(\n                    \"identity sled ''{}'' is already provisioned and active\",\n                    session_id\n                );\n            }\n            drop(cache);\n\n            // Create the container first: a sled exists ⟺ its container\n            // exists, so an incus failure means no sled row.\n            IncusPlugin::apply_create(&instance)\n                .await\n                .map_err(|e| anyhow::anyhow!(\"incus create for ''{session_id}'' failed: {e:#}\"))?;\n\n            let ts = now();\n            let sled = ContainerIdentitySled {\n                session_id: session_id.clone(),\n                wireguard_pubkey: pubkey,\n                interface: String::new(),\n                peer_ip: None,\n                mutation_index: 0,\n                hashed_footprint: String::new(),\n                trace_id: String::new(),\n                schema_version: 0,\n                vector_id: String::new(),\n                blob_ref,\n                btrfs_device,\n                instance: Some(instance),\n                session_started_at: ts,\n                last_seen_at: ts,\n                active: true,\n            };\n            let mut cache = read_cache(engine).await;\n            cache.sleds.retain(|s| s.session_id != session_id);\n            cache.sleds.push(sled.clone());\n            cache.sleds.sort_by(|a, b| a.session_id.cmp(&b.session_id));\n            write_cache(engine, &cache).await?;\n            persist_sled(&sled).await;\n\n            Ok(serde_json::json!({ \"identity\": sled }))\n        }\n\n        \"attach_btrfs_device\" => {\n            let session_id = arg_str(args, \"session_id\");\n            if session_id.is_empty() {\n                anyhow::bail!(\"attach_btrfs_device requires session_id\");\n            }\n            let mut cache = read_cache(engine).await;\n            let Some(sled) = cache.sleds.iter_mut().find(|s| s.session_id == session_id) else {\n                anyhow::bail!(\"no identity sled for session ''{}''\", session_id);\n            };\n            let Some(device) = sled.btrfs_device.clone() else {\n                anyhow::bail!(\n                    \"identity sled ''{}'' has no registered btrfs device\",\n                    session_id\n                );\n            };\n            if device.attached {\n                anyhow::bail!(\"btrfs device ''{}'' is already attached\", device.device_path);\n            }\n            if device.device_path.is_empty() || device.mount_point.is_empty() {\n                anyhow::bail!(\"btrfs device needs both device_path and mount_point\");\n            }\n\n            let dev = PathBuf::from(&device.device_path);\n            let mount = PathBuf::from(&device.mount_point);\n            tokio::task::spawn_blocking(move || op_network::btrfs::device_add(&dev, &mount))\n                .await\n                .map_err(|e| anyhow::anyhow!(\"btrfs device add task failed: {e}\"))??;\n\n            if let Some(d) = sled.btrfs_device.as_mut() {\n                d.attached = true;\n            }\n            sled.mutation_index += 1;\n            sled.last_seen_at = now();\n            let identity = sled.clone();\n            write_cache(engine, &cache).await?;\n            persist_sled(&identity).await;\n            Ok(serde_json::json!({ \"identity\": identity }))\n        }\n\n        \"touch_session\" => {\n            let session_id = arg_str(args, \"session_id\");\n            let mut cache = read_cache(engine).await;\n            let Some(sled) = cache.sleds.iter_mut().find(|s| s.session_id == session_id) else {\n                anyhow::bail!(\"no identity sled for session ''{}''\", session_id);\n            };\n            let ts = now();\n            sled.last_seen_at = ts;\n            sled.active = true;\n            write_cache(engine, &cache).await?;\n            if let Some(cozo) = sled_cozo() {\n                let cozo = cozo.clone();\n                let sid = session_id.clone();\n                match tokio::task::spawn_blocking(move || cozo.touch_identity_sled(&sid, ts, true))\n                    .await\n                {\n                    Ok(Ok(())) => {}\n                    Ok(Err(e)) => tracing::warn!(error = %e, \"identity sled touch persist failed\"),\n                    Err(e) => tracing::warn!(error = %e, \"identity sled touch task failed\"),\n                }\n            }\n            Ok(serde_json::json!({ \"success\": true }))\n        }\n\n        \"record_session_event\" => {\n            let session_id = arg_str(args, \"session_id\");\n            let kind = arg_str(args, \"kind\");\n            if session_id.is_empty() || kind.is_empty() {\n                anyhow::bail!(\"record_session_event requires session_id and kind\");\n            }\n            let subid = arg_str(args, \"subid\");\n            let content = arg_str(args, \"content\");\n            let created_at = now();\n\n            // Durable append first: Cozo allocates the seq (monotonic across\n            // restarts, unlike the capped in-state window).\n            let mut cozo_seq: Option<u64> = None;\n            if let Some(cozo) = sled_cozo() {\n                let cozo = cozo.clone();\n                let (sid, k, sb, c) = (\n                    session_id.clone(),\n                    kind.clone(),\n                    subid.clone(),\n                    content.clone(),\n                );\n                match tokio::task::spawn_blocking(move || {\n                    cozo.append_session_event(&sid, &k, &sb, &c, created_at)\n                })\n                .await\n                {\n                    Ok(Ok(seq)) => cozo_seq = Some(seq.max(0) as u64),\n                    Ok(Err(e)) => tracing::warn!(error = %e, \"session event persist failed\"),\n                    Err(e) => tracing::warn!(error = %e, \"session event persist task failed\"),\n                }\n            }\n\n            let mut cache = read_cache(engine).await;\n            let seq = cozo_seq.unwrap_or_else(|| {\n                cache\n                    .events\n                    .iter()\n                    .filter(|e| e.session_id == session_id)\n                    .map(|e| e.seq)\n                    .max()\n                    .map(|s| s + 1)\n                    .unwrap_or(0)\n            });\n            cache.events.push(SessionEvent {\n                session_id,\n                seq,\n                kind,\n                subid,\n                content,\n                created_at,\n            });\n            if cache.events.len() > MAX_EVENTS_IN_STATE {\n                let excess = cache.events.len() - MAX_EVENTS_IN_STATE;\n                cache.events.drain(..excess);\n            }\n            write_cache(engine, &cache).await?;\n            Ok(serde_json::json!({ \"success\": true }))\n        }\n\n        \"get_session_history\" => {\n            let session_id = arg_str(args, \"session_id\");\n            let limit = args.get(\"limit\").and_then(|v| v.as_u64()).unwrap_or(0) as usize;\n\n            // Prefer the durable archive; fall back to the in-state window.\n            if let Some(cozo) = sled_cozo() {\n                let cozo = cozo.clone();\n                let sid = session_id.clone();\n                match tokio::task::spawn_blocking(move || cozo.list_session_events(&sid, limit))\n                    .await\n                {\n                    Ok(Ok(rows)) => {\n                        let events: Vec<SessionEvent> = rows\n                            .iter()\n                            .map(|r| SessionEvent {\n                                session_id: r.session_id.clone(),\n                                seq: r.seq.max(0) as u64,\n                                kind: r.kind.clone(),\n                                subid: r.subid.clone(),\n                                content: r.content.clone(),\n                                created_at: r.created_at,\n                            })\n                            .collect();\n                        return Ok(serde_json::json!({ \"events\": events }));\n                    }\n                    Ok(Err(e)) => {\n                        tracing::warn!(error = %e, \"session history read failed; using cache\")\n                    }\n                    Err(e) => {\n                        tracing::warn!(error = %e, \"session history task failed; using cache\")\n                    }\n                }\n            }\n\n            let cache = read_cache(engine).await;\n            let mut events: Vec<&SessionEvent> = cache\n                .events\n                .iter()\n                .filter(|e| e.session_id == session_id)\n                .collect();\n            events.sort_by(|a, b| b.seq.cmp(&a.seq));\n            if limit > 0 {\n                events.truncate(limit);\n            }\n            Ok(serde_json::json!({ \"events\": events }))\n        }\n\n        other => Err(anyhow::anyhow!(\"unknown identity_sled method ''{}''\", other)),\n    }\n}\n\n/// Expose the typed state for consumers that want the full sled set.\npub async fn current_state(engine: &MutationEngine) -> IdentitySledState {\n    let cache = read_cache(engine).await;\n    IdentitySledState { sleds: cache.sleds }\n}","lineStart":1,"lineEnd":657,"totalLines":657,"truncated":false}},"title":"crates/op-grpc-bridge/src/identity_sled_dispatch.rs","time":{"start":1783669580799,"end":1783669580817}}}');
