({\n98:             \"available\": true,\n99:             \"schema_version\": \"1.0.0\",\n100:         })\n101:     }\n102: \n103:     pub fn schema() -> Option<PluginSchema> {\n104:         Some(rovs_commands_schema())\n105:     }\n106: }\n107: \n108: #[async_trait::async_trait]\n109: impl op_state::StatePlugin for RovsCommandsPlugin {\n110:     fn name(&self) -> &str {\n111:         \"rovs_commands\"\n112:     }\n113: \n114:     fn version(&self) -> &str {\n115:         \"1.0.0\"\n116:     }\n117: \n118:     fn schema(&self) -> Option<PluginSchema> {\n119:         Self::schema()\n120:     }\n121: \n122:     async fn calculate_diff(\n123:         &self,\n124:         _current: &Value,\n125:         _desired: &Value,\n126:     ) -> anyhow::Result<op_state::StateDiff> {\n127:         Ok(op_state::StateDiff {\n128:             plugin: self.name().to_string(),\n129:             actions: vec![],\n130:             metadata: op_state::DiffMetadata {\n131:                 timestamp: chrono::Utc::now().timestamp(),\n132:                 current_hash: \"schema-only\".to_string(),\n133:                 desired_hash: \"schema-only\".to_string(),\n134:             },\n135:         })\n136:     }\n137: \n138:     async fn apply_state(\n139:         &self,\n140:         _diff: &op_state::StateDiff,\n141:     ) -> anyhow::Result<op_state::ApplyResult> {\n142:         Ok(op_state::ApplyResult {\n143:             success: true,\n144:             changes_applied: vec![],\n145:             errors: vec![],\n146:             checkpoint: None,\n147:         })\n148:     }\n149: \n150:     async fn verify_state(&self, _desired: &Value) -> anyhow::Result<bool> {\n151:         Ok(true)\n152:     }\n153: \n154:     async fn create_checkpoint(&self) -> anyhow::Result<op_state::Checkpoint> {\n155:         Ok(op_state::Checkpoint {\n156:             id: uuid::Uuid::new_v4().to_string(),\n157:             plugin: self.name().to_string(),\n158:             timestamp: chrono::Utc::now().timestamp(