INSERT INTO part VALUES('prt_f4b12b960001NdkoLWl3YWeOuX','msg_f4b1298da001n7g8aqmSjx5wDf','ses_0b516ef36ffeY2Uc26WsdLIdZW',1783670946145,1783670947758,'{"type":"tool","tool":"bash","callID":"call_7e2f2172a4e940d59632f743","state":{"status":"completed","input":{"command":"# Force remove the broken qdrant directory\nsudo rm -rf /var/lib/incus/storage-pools/btrfs-pool/containers/qdrant 2>&1\necho \"removed dir: $?\"\n# Force remove the incus storage volume entry\nsudo incus storage volume delete btrfs-pool container/qdrant 2>&1\necho \"vol delete: $?\"\n# Now recreate\nincus launch images:ubuntu/jammy/am64 qdrant --storage btrfs-pool --profile default 2>&1\necho \"launch: $?\""},"output":"removed dir: 0\nError: Storage volumes of type \"container\" cannot be deleted with the storage API\nvol delete: 1\nLaunching qdrant\nError: Failed instance creation: Instance \"qdrant\" already exists\nlaunch: 1\n","metadata":{"output":"removed dir: 0\nError: Storage volumes of type \"container\" cannot be deleted with the storage API\nvol delete: 1\nLaunching qdrant\nError: Failed instance creation: Instance \"qdrant\" already exists\nlaunch: 1\n","exit":0,"truncated":false},"title":"# Force remove the broken qdrant directory\nsudo rm -rf /var/lib/incus/storage-pools/btrfs-pool/containers/qdrant 2>&1\necho \"removed dir: $?\"\n# Force remove the incus storage volume entry\nsudo incus storage volume delete btrfs-pool container/qdrant 2>&1\necho \"vol delete: $?\"\n# Now recreate\nincus launch images:ubuntu/jammy/am64 qdrant --storage btrfs-pool --profile default 2>&1\necho \"launch: $?\"","time":{"start":1783670947746,"end":1783670947756}}}');
