INSERT INTO part VALUES('prt_f4b2ea6c4001mCKo5MJI2GQcdI','msg_f4b2e88a8001KKXyfaE6bvfafn','ses_0b516ef36ffeY2Uc26WsdLIdZW',1783672776389,1783672777020,'{"type":"tool","tool":"bash","callID":"call_bc5d88c01f964a52a5eb1dee","state":{"status":"completed","input":{"command":"cat /etc/s6/sv/gbr-xray/run"},"output":"#!/bin/sh\n# gbr-xray - Xray REALITY egress for GhostBridge privacy chain\n\nXRAY_CONFIG=\"${XRAY_CONFIG:-/etc/xray/config.json}\"\n\nif [ ! -f \"$XRAY_CONFIG\" ]; then\n    echo \"Xray config not found: $XRAY_CONFIG\"\n    exit 0\nfi\n\nif [ -f /etc/ghostbridge/xray.env ]; then\n    . /etc/ghostbridge/xray.env\nfi\n\n# Alias 10.0.0.2 on ovsbr0 for Netmaker gRPC bridge\nip addr replace 10.0.0.2/32 dev ovsbr0 2>/dev/null || true\n\nexec 2>&1\nexec /usr/local/bin/xray run -c \"$XRAY_CONFIG\"\n","metadata":{"output":"#!/bin/sh\n# gbr-xray - Xray REALITY egress for GhostBridge privacy chain\n\nXRAY_CONFIG=\"${XRAY_CONFIG:-/etc/xray/config.json}\"\n\nif [ ! -f \"$XRAY_CONFIG\" ]; then\n    echo \"Xray config not found: $XRAY_CONFIG\"\n    exit 0\nfi\n\nif [ -f /etc/ghostbridge/xray.env ]; then\n    . /etc/ghostbridge/xray.env\nfi\n\n# Alias 10.0.0.2 on ovsbr0 for Netmaker gRPC bridge\nip addr replace 10.0.0.2/32 dev ovsbr0 2>/dev/null || true\n\nexec 2>&1\nexec /usr/local/bin/xray run -c \"$XRAY_CONFIG\"\n","exit":0,"truncated":false},"title":"cat /etc/s6/sv/gbr-xray/run","time":{"start":1783672777013,"end":1783672777018}}}');
